import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Sparkles, Sun, Cloud, CloudRain, Moon } from 'lucide-react';
import { usePetStore } from '@/store/usePetStore';
import { generateDiary } from '@/data/diaries';
import { delay } from '@/utils/helpers';

/**
 * 它的一天 - 宠物日记页面
 * 展示宠物视角的日记列表，可生成今日新日记
 */
export default function Diary() {
  const navigate = useNavigate();
  const pet = usePetStore(s => s.pet);
  const diaries = usePetStore(s => s.diaries);
  const addDiary = usePetStore(s => s.addDiary);
  const [generating, setGenerating] = useState(false);

  const weatherIcons: Record<string, JSX.Element> = {
    '晴': <Sun size={14} className="text-[#f0a050]" />,
    '多云': <Cloud size={14} className="text-[#90a0b0]" />,
    '小雨': <CloudRain size={14} className="text-[#7090b0]" />,
    '星空': <Moon size={14} className="text-[#8070a0]" />,
  };

  const moodColors: Record<string, string> = {
    '开心': '#f0c27f',
    '想念': '#a0b8d8',
    '温柔': '#d8b5d0',
    '安静': '#a8d8b9',
  };

  const handleGenerateToday = async () => {
    if (generating) return;
    setGenerating(true);
    await delay(1500);
    const newDiary = generateDiary();
    addDiary(newDiary);
    setGenerating(false);
  };

  return (
    <div className="min-h-screen pb-8">
      <div className="sticky top-9 z-10 flex items-center px-4 py-3 bg-gradient-to-b from-[#fdf6f0] to-transparent">
        <button onClick={() => navigate('/features')} className="w-10 h-10 flex items-center justify-center rounded-full bg-white/60 backdrop-blur text-[#8b6f5e] hover:bg-white/80">
          <ArrowLeft size={20} />
        </button>
        <h1 className="flex-1 text-center text-lg font-medium text-[#5a4a3a] mr-10" style={{ fontFamily: 'Georgia, serif' }}>
          📖 它的一天
        </h1>
      </div>

      <div className="px-6 max-w-md mx-auto">
        <p className="text-center text-sm text-[#a08c7a] mb-4">
          看看{pet?.name || '它'}在云上做什么
        </p>

        {/* 生成今日日记按钮 */}
        <button
          onClick={handleGenerateToday}
          disabled={generating}
          className="w-full mb-6 py-3 rounded-2xl bg-white/60 backdrop-blur border border-[#e0d0c0]/50 text-[#8b6f5e] flex items-center justify-center gap-2 hover:bg-white/80 transition-all disabled:opacity-60"
        >
          <Sparkles size={16} className={generating ? 'animate-spin' : ''} />
          <span className="text-sm">{generating ? '它正在写日记...' : '看看今天它在做什么'}</span>
        </button>

        {/* 日记列表 */}
        <div className="space-y-4">
          {diaries.map((diary, i) => (
            <div
              key={diary.id}
              className="bg-gradient-to-br from-[#fffaf3] to-[#fdf5ea] rounded-2xl p-5 border border-[#e8d8c4]/50 shadow-sm animate-fadeIn relative overflow-hidden"
              style={{ animationDelay: `${i * 80}ms`, fontFamily: 'Georgia, "Noto Serif SC", serif' }}
            >
              {/* 装饰性纸张纹理线 */}
              <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-transparent via-[#c4a48a]/20 to-transparent" />

              {/* 日期和天气 */}
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-2">
                  <span className="text-[#8b6f5e] font-medium">{diary.date}</span>
                  <div className="flex items-center gap-1 text-[#a08c7a]">
                    {weatherIcons[diary.weather] || <Sun size={14} />}
                    <span className="text-xs">{diary.weather}</span>
                  </div>
                </div>
                <span
                  className="text-xs px-2 py-0.5 rounded-full text-white"
                  style={{ background: moodColors[diary.mood] || '#c4a48a' }}
                >
                  {diary.mood}
                </span>
              </div>

              {/* 日记内容 */}
              <p className="text-[#5a4a3a] leading-loose text-sm" style={{ textIndent: '2em' }}>
                {diary.content}
              </p>

              {/* 爪印署名 */}
              <div className="mt-3 text-right">
                <span className="text-lg">🐾</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
