import { useEffect, useRef } from 'react';

/**
 * 情感粒子背景组件
 * 漂浮的爱心/星光粒子，营造温暖陪伴氛围
 * 纯 Canvas 实现，性能友好
 */
export default function ParticleBackground({ intensity = 'normal' }: { intensity?: 'normal' | 'romantic' | 'night' }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let raf: number;
    /** 粒子数组 */
    const particles: Particle[] = [];

    /** 粒子配置（根据强度模式调整） */
    const config = {
      normal: { count: 15, symbols: ['✦', '·', '∙'], colors: ['rgba(196,164,138,0.3)', 'rgba(212,184,150,0.25)'] },
      romantic: { count: 25, symbols: ['♥', '✦', '·', '♡'], colors: ['rgba(232,160,160,0.35)', 'rgba(196,164,138,0.3)', 'rgba(244,200,200,0.25)'] },
      night: { count: 40, symbols: ['✦', '·', '∙', '★'], colors: ['rgba(255,255,255,0.5)', 'rgba(200,200,255,0.3)', 'rgba(180,160,220,0.25)'] },
    }[intensity];

    /** 粒子接口 */
    interface Particle {
      x: number;
      y: number;
      size: number;
      speed: number;
      drift: number;
      symbol: string;
      color: string;
      opacity: number;
      phase: number;
    }

    /** 初始化粒子 */
    const initParticles = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      particles.length = 0;
      for (let i = 0; i < config.count; i++) {
        particles.push({
          x: Math.random() * canvas.width,
          y: Math.random() * canvas.height,
          size: 8 + Math.random() * 12,
          speed: 0.2 + Math.random() * 0.4,
          drift: (Math.random() - 0.5) * 0.3,
          symbol: config.symbols[Math.floor(Math.random() * config.symbols.length)],
          color: config.colors[Math.floor(Math.random() * config.colors.length)],
          opacity: 0.3 + Math.random() * 0.5,
          phase: Math.random() * Math.PI * 2,
        });
      }
    };

    /** 动画循环 */
    const tick = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const time = Date.now() / 1000;

      particles.forEach(p => {
        // 向上漂浮
        p.y -= p.speed;
        // 左右轻微飘动
        p.x += Math.sin(time + p.phase) * p.drift;

        // 超出顶部则从底部重生
        if (p.y < -20) {
          p.y = canvas.height + 20;
          p.x = Math.random() * canvas.width;
        }

        // 透明度呼吸
        const breathOpacity = p.opacity * (0.6 + 0.4 * Math.sin(time * 1.5 + p.phase));

        // 绘制粒子符号
        ctx.save();
        ctx.globalAlpha = breathOpacity;
        ctx.fillStyle = p.color;
        ctx.font = `${p.size}px Georgia, serif`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(p.symbol, p.x, p.y);
        ctx.restore();
      });

      raf = requestAnimationFrame(tick);
    };

    initParticles();
    tick();

    const handleResize = () => initParticles();
    window.addEventListener('resize', handleResize);

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener('resize', handleResize);
    };
  }, [intensity]);

  return (
    <canvas
      ref={canvasRef}
      className="fixed inset-0 pointer-events-none z-0"
      style={{ width: '100vw', height: '100vh' }}
    />
  );
}
