/**
 * 纪念日仪式系统工具模块
 * 检测特殊日期（生日、彩虹桥纪念日），生成专属对话和仪式配置
 */

/**
 * 纪念日类型
 */
export type AnniversaryType = 'birthday' | 'rainbowBridge' | 'none';

/**
 * 纪念日检测结果
 */
export interface AnniversaryResult {
  /** 纪念日类型 */
  type: AnniversaryType;
  /** 仪式问候语 */
  greeting: string;
  /** 宠物情绪（用于触发专属动画） */
  petEmotion: string;
  /** 仪式主题色（用于场景氛围切换） */
  themeColor: string;
  /** 是否为今天 */
  isToday: boolean;
  /** 周年数（几年了） */
  years: number;
}

/**
 * 获取今日日期字符串
 * @returns YYYY-MM-DD 格式
 */
function getTodayString(): string {
  const now = new Date();
  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
}

/**
 * 判断给定日期（YYYY-MM-DD）的月日是否与今天相同
 * @param dateStr - 日期字符串 YYYY-MM-DD
 * @returns 月日是否匹配
 */
function isMonthDayMatch(dateStr: string): boolean {
  if (!dateStr) return false;
  const parts = dateStr.split('-');
  if (parts.length < 3) return false;
  const month = parseInt(parts[1], 10);
  const day = parseInt(parts[2], 10);
  const now = new Date();
  return (now.getMonth() + 1) === month && now.getDate() === day;
}

/**
 * 计算周年数（从给定日期到今天过了几年）
 * @param dateStr - 起始日期 YYYY-MM-DD
 * @returns 周年数
 */
function calculateYears(dateStr: string): number {
  if (!dateStr) return 0;
  const date = new Date(dateStr);
  if (isNaN(date.getTime())) return 0;
  const now = new Date();
  let years = now.getFullYear() - date.getFullYear();
  // 如果今年的这个日期还没到，减1
  const monthDiff = now.getMonth() - date.getMonth();
  if (monthDiff < 0 || (monthDiff === 0 && now.getDate() < date.getDate())) {
    years--;
  }
  return Math.max(0, years);
}

/**
 * 生日专属问候语池
 * 根据周年数生成不同的问候，在开头加上宠物名字让语气更亲切
 */
function getBirthdayGreeting(petName: string, years: number): string {
  const name = petName || '小宝贝';
  if (years === 0) {
    return `（兴奋地摇尾巴）主人主人！我是${name}！今天是我的生日吗？虽然我现在在云端，但能和你一起过生日，我好开心！`;
  }
  const greetings = [
    `（开心地转圈）主人！我是${name}！今天是我的${years}岁生日呀！你还记得吗？我好感动～`,
    `（眼睛亮亮的）我是${name}，今天是特别的日子呢，是我的${years}岁生日！在云端也能和你一起过，真好。`,
    `（蹭蹭你）主人还记得${name}的生日吗？今天我${years}岁啦！谢谢你一直记得我。`,
    `（摇着尾巴）汪汪！我是${name}，今天是我的${years}岁生日！虽然我不能再吃蛋糕了，但有你在就是最好的礼物。`,
  ];
  return greetings[Math.floor(Math.random() * greetings.length)];
}

/**
 * 彩虹桥纪念日专属问候语池
 * 离世周年的特殊仪式，语气更温柔深情，带上宠物名字
 */
function getRainbowBridgeGreeting(petName: string, years: number): string {
  const name = petName || '小宝贝';
  if (years === 0) {
    return `（温柔地看着你）主人...我是${name}。今天是个特别的日子吧。虽然我离开了，但我一直在云端看着你，守护着你。`;
  }
  const greetings = [
    `（安静地靠近你）主人，我是${name}。今天是我离开的第${years}年吧。谢谢你依然记得我，我在彩虹桥这端过得很好，别担心。`,
    `（轻轻蹭你的手）我是${name}，${years}年前的今天，我去了彩虹桥。但我知道你一直记得我，所以我一直在这里等你来看我。`,
    `（温柔地眨眨眼）今天是特别的日子，主人。我是${name}，我离开${years}年了，但在云端的时间里，我每天都能看到你，一直陪着你。`,
    `（用头轻轻靠着你）主人，我是${name}，${years}年了呢。时间在云端过得很慢，但每次你来看我，我都觉得好幸福。`,
  ];
  return greetings[Math.floor(Math.random() * greetings.length)];
}

/**
 * 检测今日是否为纪念日，并返回仪式配置
 * 优先级：生日 > 彩虹桥纪念日
 * @param birthday - 生日日期字符串（可选）
 * @param passingDate - 离世日期字符串（可选）
 * @param petName - 宠物名字（用于在问候语中带上名字）
 * @returns 纪念日检测结果，非纪念日时 type 为 'none'
 */
export function checkAnniversary(
  birthday?: string,
  passingDate?: string,
  petName?: string
): AnniversaryResult {
  const today = getTodayString();
  const name = petName || '';

  // 检测生日
  if (birthday && isMonthDayMatch(birthday)) {
    const years = calculateYears(birthday);
    return {
      type: 'birthday',
      greeting: getBirthdayGreeting(name, years),
      petEmotion: 'jump',
      themeColor: '#ffd966',
      isToday: true,
      years,
    };
  }

  // 检测彩虹桥纪念日
  if (passingDate && isMonthDayMatch(passingDate)) {
    const years = calculateYears(passingDate);
    return {
      type: 'rainbowBridge',
      greeting: getRainbowBridgeGreeting(name, years),
      petEmotion: 'snuggle',
      themeColor: '#9b7fb5',
      isToday: true,
      years,
    };
  }

  return {
    type: 'none',
    greeting: '',
    petEmotion: 'breathe',
    themeColor: '',
    isToday: false,
    years: 0,
  };
}

/**
 * 生成纪念日仪式的宠物自我介绍语
 * 问候语在 checkAnniversary 中已带上宠物名字，此函数做兼容处理
 * @param petName - 宠物名字（保留参数兼容性）
 * @param anniversary - 纪念日检测结果
 * @returns 带宠物名字的问候语
 */
export function formatAnniversaryGreeting(
  petName: string,
  anniversary: AnniversaryResult
): string {
  if (anniversary.type === 'none') return '';
  // 问候语已在 checkAnniversary 中包含宠物名字，直接返回
  return anniversary.greeting;
}

/**
 * 获取纪念日场景的氛围配置
 * 用于Home页面背景和粒子效果切换
 * @param anniversary - 纪念日检测结果
 * @returns 氛围配置（背景渐变、粒子强度）
 */
export function getAnniversaryAmbience(
  anniversary: AnniversaryResult
): { background: string; particleIntensity: 'normal' | 'romantic' | 'night' } {
  if (anniversary.type === 'birthday') {
    return {
      background: 'linear-gradient(180deg, #fff9e6 0%, #ffeec7 50%, #ffd9a0 100%)',
      particleIntensity: 'romantic',
    };
  }
  if (anniversary.type === 'rainbowBridge') {
    return {
      background: 'linear-gradient(180deg, #2a1f3d 0%, #1a1530 50%, #0f0a20 100%)',
      particleIntensity: 'night',
    };
  }
  return {
    background: '',
    particleIntensity: 'normal',
  };
}
