import { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Send, Download, Heart } from 'lucide-react';
import { usePetStore } from '@/store/usePetStore';
import { randomPick } from '@/utils/helpers';
import { delay } from '@/utils/helpers';

/**
 * 彩虹桥明信片页面
 * 写信给宠物，生成带爪印的回明信片
 */
export default function Postcard() {
  const navigate = useNavigate();
  const pet = usePetStore(s => s.pet);
  const addPostcard = usePetStore(s => s.addPostcard);
  const postcards = usePetStore(s => s.postcards);

  const [message, setMessage] = useState('');
  const [generating, setGenerating] = useState(false);
  const [currentCard, setCurrentCard] = useState<{ userMsg: string; petReply: string } | null>(null);
  const cardRef = useRef<HTMLDivElement>(null);

  const petReplies = [
    `谢谢你写给我的信，我在彩虹桥这边收到了哦。这里每天都是晴天，有跑不完的草地和吃不完的小零食。你不用一直想我，要好好吃饭，好好睡觉。想我的时候就看看风吧，风里有我蹭你的味道。永远爱你。`,
    `哇！收到你的信好开心！我在这边交了好多朋友，但还是最想你。你送给我的小毯子我一直带着呢，暖暖的。不要哭哦，我一直都在你身边，只是换了一种方式陪着你。`,
    `你的字还是那么好看～我反复看了好多遍。这边的云软软的，我每天都趴在上面看你。你笑的时候我也开心，你哭的时候我就用爪子拍拍你的手背，只是你感觉不到而已。我很好，你也要好好的。`,
    `信收到啦！我在这边学会了新技能——可以在彩虹上面跑来跑去！等你的时候我就坐在桥头看人间，找你窗户亮着灯的方向。你要加油生活呀，等很久很久以后我们再见的时候，我要第一个扑进你怀里。`,
  ];

  const handleSend = async () => {
    const text = message.trim();
    if (!text || generating) return;
    setGenerating(true);
    await delay(2000);
    const reply = randomPick(petReplies);
    setCurrentCard({ userMsg: text, petReply: reply });
    addPostcard({ userMessage: text, petReply: reply });
    setGenerating(false);
    setMessage('');
  };

  const handleSave = () => {
    alert('明信片已保存到记忆空间（Demo模式：实际可使用html2canvas保存为图片）');
  };

  return (
    <div className="min-h-screen pb-8">
      <div className="sticky top-9 z-10 flex items-center px-4 py-3 bg-gradient-to-b from-[#fdf6f0] to-transparent">
        <button onClick={() => navigate('/features')} className="w-10 h-10 flex items-center justify-center rounded-full bg-white/60 backdrop-blur text-[#8b6f5e] hover:bg-white/80">
          <ArrowLeft size={20} />
        </button>
        <h1 className="flex-1 text-center text-lg font-medium text-[#5a4a3a] mr-10" style={{ fontFamily: 'Georgia, serif' }}>
          💌 彩虹桥明信片
        </h1>
      </div>

      <div className="px-6 max-w-md mx-auto">
        <p className="text-center text-sm text-[#a08c7a] mb-6">
          写一封信，寄到彩虹桥那边
        </p>

        {/* 明信片展示区 */}
        {(currentCard || generating) && (
          <div
            ref={cardRef}
            className="relative rounded-2xl overflow-hidden mb-6 shadow-xl animate-fadeIn"
            style={{
              background: 'linear-gradient(135deg, #fff9f0 0%, #fdf0e0 30%, #f8e8ff 70%, #e8e0f8 100%)',
              aspectRatio: '3/4',
            }}
          >
            {generating ? (
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <div className="text-4xl animate-breathe mb-4">🐾</div>
                <p className="text-[#8b6f5e] text-sm animate-pulse">信正在飘向彩虹桥...</p>
                <div className="flex gap-1 mt-4">
                  <span className="w-2 h-2 bg-[#c4a48a] rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                  <span className="w-2 h-2 bg-[#c4a48a] rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                  <span className="w-2 h-2 bg-[#c4a48a] rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                </div>
              </div>
            ) : currentCard && (
              <div className="absolute inset-0 p-6 flex flex-col">
                {/* 装饰边框 */}
                <div className="absolute inset-3 border border-[#c4a48a]/20 rounded-xl pointer-events-none" />

                {/* 收件人 */}
                <div className="text-center mb-4">
                  <p className="text-xs text-[#b0a090] tracking-widest">TO</p>
                  <p className="text-[#8b6f5e] font-medium" style={{ fontFamily: 'Georgia, serif' }}>
                    亲爱的 {pet?.name || '宝贝'}
                  </p>
                </div>

                {/* 邮票区域 */}
                <div className="absolute top-4 right-4 w-12 h-14 border-2 border-[#c4a48a]/40 rounded flex items-center justify-center rotate-6 bg-white/30">
                  <span className="text-xl">🌈</span>
                </div>

                {/* 用户写的话 */}
                <div className="flex-1 px-2">
                  <div className="bg-white/40 rounded-lg p-3 mb-3">
                    <p className="text-xs text-[#a08c7a] mb-1">你写的：</p>
                    <p className="text-sm text-[#5a4a3a] leading-relaxed">{currentCard.userMsg}</p>
                  </div>

                  {/* 宠物回信 */}
                  <div className="relative">
                    <div className="flex items-center gap-1 mb-1">
                      <span className="text-sm">🐾</span>
                      <p className="text-xs text-[#8b6f5e]">它的回信：</p>
                    </div>
                    <p className="text-sm text-[#5a4a3a] leading-loose italic" style={{ fontFamily: 'Georgia, "Noto Serif SC", serif' }}>
                      {currentCard.petReply}
                    </p>
                  </div>
                </div>

                {/* 爪印署名 */}
                <div className="flex items-end justify-between mt-3">
                  <div />
                  <div className="text-right">
                    <div className="text-2xl mb-1">🐾</div>
                    <p className="text-xs text-[#b0a090] italic">—— 永远爱你的 {pet?.name || '它'}</p>
                  </div>
                </div>

                {/* 彩虹装饰 */}
                <div className="absolute bottom-0 left-0 right-0 h-2 bg-gradient-to-r from-[#ff9a9e] via-[#fecfef] to-[#a18cd1] opacity-30" />
              </div>
            )}
          </div>
        )}

        {/* 保存按钮 */}
        {currentCard && (
          <button
            onClick={handleSave}
            className="w-full flex items-center justify-center gap-2 py-3 rounded-xl bg-white/60 border border-[#e0d0c0]/50 text-[#8b6f5e] text-sm mb-4 hover:bg-white/80 transition-colors"
          >
            <Download size={16} />
            <span>保存明信片</span>
          </button>
        )}

        {/* 写信区 */}
        {!generating && (
          <div className="bg-white/60 backdrop-blur rounded-2xl p-4 border border-[#e0d0c0]/50">
            <textarea
              value={message}
              onChange={e => setMessage(e.target.value)}
              placeholder={`亲爱的${pet?.name || '宝贝'}：\n我想对你说...`}
              rows={5}
              className="w-full bg-transparent text-sm text-[#5a4a3a] placeholder-[#c4b4a4] outline-none resize-none leading-relaxed"
            />
            <div className="flex justify-end mt-2">
              <button
                onClick={handleSend}
                disabled={!message.trim()}
                className={`flex items-center gap-2 px-5 py-2 rounded-full text-sm transition-all ${
                  message.trim()
                    ? 'bg-gradient-to-r from-[#b4a0dc] to-[#9080c0] text-white shadow-md'
                    : 'bg-[#e0d0c0] text-[#a09080]'
                }`}
              >
                <Send size={14} />
                <span>寄出去</span>
              </button>
            </div>
          </div>
        )}

        {/* 历史明信片数量 */}
        {postcards.length > 0 && !currentCard && (
          <div className="mt-4 text-center">
            <p className="text-xs text-[#b0a090] flex items-center justify-center gap-1">
              <Heart size={12} />
              你已经寄了 {postcards.length} 张明信片
            </p>
          </div>
        )}
      </div>
    </div>
  );
}
