import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft } from 'lucide-react';
import { usePetStore } from '@/store/usePetStore';
import { delay } from '@/utils/helpers';

/**
 * 告别仪式页面
 * 多步骤引导：点蜡烛→翻看回忆→说再见→完成
 */
export default function Goodbye() {
  const navigate = useNavigate();
  const pet = usePetStore(s => s.pet);
  const [step, setStep] = useState(0);
  const [candleLit, setCandleLit] = useState(false);
  const [fadeOut, setFadeOut] = useState(false);
  const [showStars, setShowStars] = useState(false);

  const steps = [
    { title: '点一支蜡烛', desc: '为它点一支蜡烛，照亮通往彩虹桥的路', action: '点燃蜡烛' },
    { title: '回忆在一起的时光', desc: '那些一起晒过太阳、一起散过步的日子', action: '我记得' },
    { title: '说出再见', desc: '好好说一声再见，不是结束，是换种方式陪伴', action: '再见了，宝贝' },
    { title: '', desc: '', action: '' },
  ];

  useEffect(() => {
    if (step === 3) {
      setShowStars(true);
    }
  }, [step]);

  const handleNext = async () => {
    if (step === 0) {
      setCandleLit(true);
      await delay(1500);
    }
    if (step === 2) {
      setFadeOut(true);
      await delay(2000);
    }
    if (step < 3) {
      setStep(step + 1);
    }
  };

  // 完成页 - 星空效果
  if (step === 3) {
    return (
      <div className="fixed inset-0 z-50 flex flex-col items-center justify-center" style={{ background: 'linear-gradient(to bottom, #0a0a1a, #1a1028, #2c1f3a)' }}>
        {/* 星星 */}
        {showStars && Array.from({ length: 50 }).map((_, i) => (
          <div
            key={i}
            className="absolute rounded-full bg-white animate-twinkle"
            style={{
              width: Math.random() * 3 + 1 + 'px',
              height: Math.random() * 3 + 1 + 'px',
              left: Math.random() * 100 + '%',
              top: Math.random() * 70 + '%',
              animationDelay: Math.random() * 2 + 's',
              animationDuration: (Math.random() * 2 + 1) + 's',
            }}
          />
        ))}

        {/* 光粒子上升 */}
        {showStars && Array.from({ length: 12 }).map((_, i) => (
          <div
            key={`p-${i}`}
            className="absolute w-2 h-2 rounded-full animate-particle-up"
            style={{
              background: `radial-gradient(circle, #f0d0a0, transparent)`,
              left: (30 + Math.random() * 40) + '%',
              bottom: '30%',
              animationDelay: (i * 0.3) + 's',
              animationDuration: '3s',
            }}
          />
        ))}

        <div className={`relative z-10 text-center px-6 transition-all duration-1000 ${showStars ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
          <div className="text-6xl mb-6">🐾</div>
          <h2 className="text-2xl text-white/90 mb-4" style={{ fontFamily: 'Georgia, serif' }}>
            它已经收到了你的心意
          </h2>
          <p className="text-white/60 text-sm leading-loose max-w-xs mx-auto mb-8">
            再见不是遗忘，<br/>
            而是把它放在心里最柔软的地方。<br/>
            想它的时候，就随时回来看看。<br/>
            <br/>
            它一直都在，<br/>
            在风里，在阳光里，在你心里。
          </p>
          <button
            onClick={() => navigate('/home')}
            className="px-8 py-3 bg-white/10 backdrop-blur border border-white/20 rounded-full text-white/80 text-sm hover:bg-white/20 transition-colors"
          >
            回到{pet?.name || '它'}身边
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-50 flex flex-col" style={{ background: fadeOut ? '#0a0a1a' : 'linear-gradient(to bottom, #2c1f3a, #1a1028)' }}>
      {/* 返回按钮 */}
      {!fadeOut && (
        <button
          onClick={() => navigate('/memory')}
          className="absolute top-4 left-4 w-10 h-10 flex items-center justify-center rounded-full bg-white/10 text-white/60 hover:bg-white/20 z-10"
        >
          <ArrowLeft size={20} />
        </button>
      )}

      {/* 蜡烛区域 */}
      <div className="flex-1 flex flex-col items-center justify-center px-8">
        {/* 蜡烛 */}
        <div className={`transition-all duration-1000 ${fadeOut ? 'opacity-0 scale-50' : 'opacity-100'}`}>
          <div className="relative mb-8">
            {/* 火焰 */}
            {candleLit && step >= 0 && (
              <div className="absolute -top-8 left-1/2 -translate-x-1/2">
                <div className="w-6 h-10 bg-gradient-to-t from-[#ff6b35] via-[#ffb347] to-[#fff4e0] rounded-full animate-flicker origin-bottom" style={{ borderRadius: '50% 50% 50% 50% / 60% 60% 40% 40%' }} />
                <div className="absolute top-0 left-1/2 -translate-x-1/2 w-3 h-5 bg-gradient-to-t from-[#ffb347] to-[#fff8e0] rounded-full animate-flicker" style={{ borderRadius: '50% 50% 50% 50% / 60% 60% 40% 40%', animationDelay: '0.1s' }} />
                {/* 光晕 */}
                <div className="absolute -top-4 -left-8 w-20 h-20 bg-[#ffb347]/20 rounded-full blur-xl" />
              </div>
            )}

            {/* 蜡烛本体 */}
            <div className="w-8 h-24 bg-gradient-to-b from-[#f5e6d3] to-[#e8d4bc] rounded-t-sm mx-auto relative">
              <div className="absolute top-0 left-1/2 -translate-x-1/2 w-0.5 h-2 bg-[#333]" />
            </div>
            {/* 烛台 */}
            <div className="w-16 h-3 bg-[#c4a48a] rounded-full mx-auto shadow-lg" />
            <div className="w-12 h-2 bg-[#a08070] rounded-b-lg mx-auto" />
          </div>
        </div>

        {/* 文字内容 */}
        {!fadeOut && (
          <div className="text-center animate-fadeIn" key={step}>
            <h2 className="text-xl text-white/90 mb-3" style={{ fontFamily: 'Georgia, serif' }}>
              {steps[step].title}
            </h2>
            <p className="text-white/50 text-sm leading-relaxed max-w-xs mx-auto mb-10">
              {steps[step].desc}
            </p>

            <button
              onClick={handleNext}
              className="px-8 py-3 bg-white/10 backdrop-blur border border-white/20 rounded-full text-white/80 text-sm hover:bg-white/20 transition-colors"
            >
              {steps[step].action}
            </button>
          </div>
        )}

        {/* 步骤指示器 */}
        {!fadeOut && (
          <div className="absolute bottom-12 flex gap-2">
            {[0, 1, 2].map(i => (
              <div
                key={i}
                className={`w-2 h-2 rounded-full transition-all ${
                  i <= step ? 'bg-[#f0d0a0]' : 'bg-white/20'
                }`}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
