/**
 * 混合两个颜色值
 */
function blendColors(c1: string, c2: string, ratio: number = 0.5): string {
  const hex = (s: string) => parseInt(s, 16);
  const r = Math.round(hex(c1.slice(1, 3)) * (1 - ratio) + hex(c2.slice(1, 3)) * ratio);
  const g = Math.round(hex(c1.slice(3, 5)) * (1 - ratio) + hex(c2.slice(3, 5)) * ratio);
  const b = Math.round(hex(c1.slice(5, 7)) * (1 - ratio) + hex(c2.slice(5, 7)) * ratio);
  return `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`;
}

/**
 * 变亮颜色
 */
function lightenColor(color: string, amount: number = 0.3): string {
  const hex = (s: string) => parseInt(s, 16);
  const r = Math.min(255, hex(color.slice(1, 3)) + Math.round(255 * amount));
  const g = Math.min(255, hex(color.slice(3, 5)) + Math.round(255 * amount));
  const b = Math.min(255, hex(color.slice(5, 7)) + Math.round(255 * amount));
  return `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`;
}

/**
 * 变暗颜色
 */
function darkenColor(color: string, amount: number = 0.3): string {
  const hex = (s: string) => parseInt(s, 16);
  const r = Math.max(0, hex(color.slice(1, 3)) - Math.round(255 * amount));
  const g = Math.max(0, hex(color.slice(3, 5)) - Math.round(255 * amount));
  const b = Math.max(0, hex(color.slice(5, 7)) - Math.round(255 * amount));
  return `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`;
}

/**
 * 获取宠物颜色配置 - 增强版：自动生成渐变所需的多层颜色
 */
function getPetColors(pet: Pet) {
  const defaultColors: { body: string; ear: string; belly: string; pattern?: string } = { body: '#d8b898', ear: '#c0a080', belly: '#f0e0d0' };
  const breedStr = pet.breed || '';
  let c: { body: string; ear: string; belly: string; pattern?: string } = defaultColors;

  if (breedStr.includes(' × ')) {
    const [b1, b2] = breedStr.split(' × ');
    const c1 = breedColors[b1];
    const c2 = breedColors[b2];
    if (c1 && c2) {
      c = {
        body: blendColors(c1.body, c2.body, 0.5),
        ear: blendColors(c1.ear, c2.ear, 0.5),
        belly: blendColors(c1.belly, c2.belly, 0.5),
        pattern: c1.pattern,
      };
    } else if (c1) c = c1;
    else if (c2) c = c2;
  } else {
    const breedKey = Object.keys(breedColors).find(k => breedStr.includes(k));
    if (breedKey) c = breedColors[breedKey];
    else if (pet.species === 'dog') c = breedColors['中华田园犬'] || defaultColors;
    else if (pet.species === 'cat') c = breedColors['中华田园猫'] || defaultColors;
    else if (pet.species === 'rabbit') c = { body: '#f5e0e0', ear: '#e8c8c8', belly: '#fdf0f0' };
    else if (pet.species === 'hamster') c = { body: '#e8c890', ear: '#d8b078', belly: '#f5dfb0' };
    else if (pet.species === 'bird') c = { body: '#7bc8a0', ear: '#5ab088', belly: '#a0e0c0' };
  }

  // 生成多层次颜色用于渐变
  return {
    body: c.body,
    bodyLight: lightenColor(c.body, 0.25),
    bodyDark: darkenColor(c.body, 0.2),
    bodyShadow: darkenColor(c.body, 0.4),
    ear: c.ear,
    earLight: lightenColor(c.ear, 0.2),
    earDark: darkenColor(c.ear, 0.3),
    belly: c.belly,
    bellyLight: lightenColor(c.belly, 0.15),
    pattern: c.pattern,
  };
}

