/**
 * 语音陪伴工具模块（神经语音版）
 *
 * 核心升级：从浏览器Web Speech API 改为调用微软Edge神经语音TTS
 * - 通过Electron后端调用edge-tts-nodejs，使用微软Azure神经语音引擎
 * - 质量远超浏览器内置合成语音，接近真人发音
 * - 默认使用晓晓(zh-CN-XiaoxiaoNeural)年轻女声，高音调模拟孩子感
 * - 完全免费，无需API Key
 *
 * 同时保留STT语音识别功能（使用浏览器内置Web Speech API）
 */

/** 当前音频元素（用于播放TTS音频） */
let currentAudio: HTMLAudioElement | null = null;

/** 当前是否正在播报语音 */
let isSpeaking = false;

/** 当前是否正在监听语音输入 */
let isListening = false;

/** 当前语音识别实例 */
let recognitionInstance: any = null;

/** TTS合成请求的AbortController（用于取消正在进行的合成） */
let synthesisAbortController: AbortController | null = null;

/** Electron API 类型声明（仅TTS相关） */
interface TTSAPI {
  ttsSynthesize: (params: {
    text: string;
    voice?: string;
    rate?: number;
    pitch?: number;
    volume?: number;
  }) => Promise<{ success: boolean; audioBase64?: string; error?: string }>;
}

/**
 * 获取 Electron TTS API
 * @returns TTS API 或 null（非Electron环境）
 */
function getTTSAPI(): TTSAPI | null {
  return (window as Window & { electronAPI?: TTSAPI }).electronAPI ?? null;
}

/**
 * 检测是否支持神经语音TTS（需要Electron环境）
 * @returns 是否支持神经语音
 */
export function isTTSSupported(): boolean {
  return getTTSAPI() !== null;
}

/**
 * 检测浏览器是否支持语音识别
 * @returns 是否支持 STT
 */
export function isSTTSupported(): boolean {
  return typeof window !== 'undefined' &&
    ('SpeechRecognition' in window || 'webkitSpeechRecognition' in window);
}

/**
 * 初始化TTS（兼容接口，神经语音版本无需初始化）
 */
export function initTTS(): void {
  // 神经语音版本无需初始化，保留接口兼容性
}

/**
 * 语音播报文本（神经语音TTS）
 *
 * 调用Electron后端的edge-tts-nodejs合成音频，
 * 返回mp3 base64后用HTML5 Audio播放
 *
 * 优势：
 * 1. 微软Azure神经语音引擎，接近真人发音
 * 2. 晓晓年轻女声 + 高音调，模拟孩子/小动物感
 * 3. 自动过滤括号内动作描述，只朗读正文
 *
 * @param text - 要播报的文本
 * @param options - 可选参数：voice（声音名）、rate（语速偏移）、pitch（音调偏移）
 */
export async function speak(
  text: string,
  options?: { voice?: string; rate?: number; pitch?: number; volume?: number }
): Promise<void> {
  const ttsAPI = getTTSAPI();
  if (!ttsAPI || !text) return;

  // 停止当前正在播报的语音
  cancelSpeak();

  // 取消正在进行的合成请求
  if (synthesisAbortController) {
    synthesisAbortController.abort();
  }
  synthesisAbortController = new AbortController();

  isSpeaking = true;

  try {
    /**
     * 语音参数（模拟可爱女童声）：
     * - voice: 晓晓（zh-CN-XiaoxiaoNeural，年轻女声，配合高音调最接近女童感）
     * - rate: -20（较慢语速，让孩子说话更可爱）
     * - pitch: +50Hz（大幅提高音调，模拟女童的高频声音特质）
     *
     * 不同情绪使用不同的语速和音调
     */
    let rate = options?.rate ?? -20;
    let pitch = options?.pitch ?? 50;

    // 根据文本内容自动调整语速和音调（让语音更有感情）
    if (/[？?]$/.test(text.trim())) {
      // 问句：音调更高，表达好奇
      pitch = 60;
      rate = -25;
    } else if (/[！!]$/.test(text.trim())) {
      // 感叹句：语速稍快，表达兴奋
      pitch = 55;
      rate = -15;
    } else if (text.includes('...') || text.includes('…')) {
      // 带省略号：语速慢，表达犹豫或温柔
      pitch = 45;
      rate = -30;
    }

    const result = await ttsAPI.ttsSynthesize({
      text,
      voice: options?.voice,
      rate: options?.rate ?? rate,
      pitch: options?.pitch ?? pitch,
      volume: options?.volume,
    });

    // 如果已被取消，不播放
    if (synthesisAbortController?.signal.aborted) return;

    if (result.success && result.audioBase64) {
      // 创建Audio元素播放mp3
      currentAudio = new Audio(result.audioBase64);
      currentAudio.onended = () => {
        isSpeaking = false;
        currentAudio = null;
      };
      currentAudio.onerror = () => {
        isSpeaking = false;
        currentAudio = null;
      };
      await currentAudio.play();
    } else {
      isSpeaking = false;
      console.warn('TTS合成失败:', result.error);
    }
  } catch (err) {
    isSpeaking = false;
    console.error('TTS播放出错:', err);
  }
}

/**
 * 停止当前语音播报
 */
export function cancelSpeak(): void {
  if (currentAudio) {
    currentAudio.pause();
    currentAudio = null;
  }
  isSpeaking = false;
}

/**
 * 获取当前是否正在播报语音
 * @returns 是否正在播报
 */
export function getIsSpeaking(): boolean {
  return isSpeaking;
}

/**
 * 开始监听语音输入（STT）
 * 使用浏览器内置语音识别，识别结果通过回调返回
 * @param onResult - 识别到文本时的回调
 * @param onEnd - 识别结束时的回调（正常结束或出错）
 * @param options - 可选参数：连续识别、中间结果
 */
export function startListening(
  onResult: (text: string, isFinal: boolean) => void,
  onEnd?: () => void,
  options?: { continuous?: boolean; interimResults?: boolean }
): void {
  if (!isSTTSupported() || isListening) return;

  const SpeechRecognitionClass =
    (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
  if (!SpeechRecognitionClass) return;

  const recognition = new SpeechRecognitionClass();
  recognition.lang = 'zh-CN';
  recognition.continuous = options?.continuous ?? false;
  recognition.interimResults = options?.interimResults ?? true;

  recognition.onresult = (event: any) => {
    let finalText = '';
    let interimText = '';
    for (let i = event.resultIndex; i < event.results.length; i++) {
      const transcript = event.results[i][0].transcript;
      if (event.results[i].isFinal) {
        finalText += transcript;
      } else {
        interimText += transcript;
      }
    }
    if (finalText) {
      onResult(finalText, true);
    } else if (interimText) {
      onResult(interimText, false);
    }
  };

  recognition.onerror = () => {
    isListening = false;
    recognitionInstance = null;
    onEnd?.();
  };

  recognition.onend = () => {
    isListening = false;
    recognitionInstance = null;
    onEnd?.();
  };

  recognitionInstance = recognition;
  isListening = true;
  recognition.start();
}

/**
 * 停止语音识别监听
 */
export function stopListening(): void {
  if (recognitionInstance) {
    try {
      recognitionInstance.stop();
    } catch (err) {
      // 忽略停止时的错误
    }
    recognitionInstance = null;
    isListening = false;
  }
}

/**
 * 获取当前是否正在监听语音输入
 * @returns 是否正在监听
 */
export function getIsListening(): boolean {
  return isListening;
}
