export function generateId(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2);
}

export function randomPick<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

export function formatTime(date?: Date): string {
  const d = date || new Date();
  return `${d.getHours().toString().padStart(2, '0')}:${d.getMinutes().toString().padStart(2, '0')}`;
}

export function delay(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

export async function typeWriter(
  text: string,
  onChar: (char: string, fullText: string) => void,
  speed: number = 50
): Promise<void> {
  let current = '';
  for (const char of text) {
    current += char;
    onChar(char, current);
    await delay(speed + Math.random() * 30);
  }
}

/**
 * 压缩图片到指定尺寸和质量，返回base64
 */
export function compressImage(file: File, maxSize: number = 256, quality: number = 0.7): Promise<string> {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let { width, height } = img;
        if (width > height) {
          if (width > maxSize) {
            height = (height * maxSize) / width;
            width = maxSize;
          }
        } else {
          if (height > maxSize) {
            width = (width * maxSize) / height;
            height = maxSize;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', quality));
        } else {
          resolve(e.target?.result as string);
        }
      };
      img.onerror = () => resolve(e.target?.result as string);
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  });
}

export function saveToStorage<T>(key: string, data: T): void {
  try {
    localStorage.setItem(key, JSON.stringify(data));
  } catch (e) {
    console.warn('Failed to save to localStorage:', e);
  }
}

export function loadFromStorage<T>(key: string, defaultValue: T): T {
  try {
    const stored = localStorage.getItem(key);
    if (stored) {
      return JSON.parse(stored) as T;
    }
  } catch (e) {
    console.warn('Failed to load from localStorage:', e);
  }
  return defaultValue;
}

/**
 * 根据宠物信息构建 AI 图片生成 prompt
 * 将品种、物种、特征等转换为英文描述以获得最佳生成效果
 */
export function buildPetPrompt(species: string, breed: string, features: string): string {
  const speciesMap: Record<string, string> = {
    dog: 'dog',
    cat: 'cat',
    rabbit: 'rabbit',
    hamster: 'hamster',
    bird: 'bird',
  };

  const breedEn: Record<string, string> = {
    '金毛寻回犬': 'Golden Retriever', '拉布拉多': 'Labrador', '柯基': 'Corgi',
    '柴犬': 'Shiba Inu', '秋田犬': 'Akita', '泰迪/贵宾': 'Poodle',
    '比熊': 'Bichon Frise', '博美': 'Pomeranian', '萨摩耶': 'Samoyed',
    '哈士奇': 'Husky', '阿拉斯加': 'Alaskan Malamute', '边境牧羊犬': 'Border Collie',
    '德国牧羊犬': 'German Shepherd', '中华田园犬': 'Chinese rural dog',
    '英国短毛猫': 'British Shorthair', '美国短毛猫': 'American Shorthair',
    '布偶猫': 'Ragdoll', '暹罗猫': 'Siamese', '波斯猫': 'Persian',
    '缅因猫': 'Maine Coon', '橘猫': 'orange tabby cat', '狸花猫': 'tabby cat',
    '中华田园猫': 'Chinese rural cat', '荷兰垂耳兔': 'Holland Lop rabbit',
    '侏儒兔': 'Netherland Dwarf rabbit', '三线仓鼠': 'Dwarf hamster',
    '金丝熊': 'Syrian hamster', '虎皮鹦鹉': 'Budgerigar', '玄凤鹦鹉': 'Cockatiel',
  };

  const animalType = speciesMap[species] || 'pet';
  const breedName = breedEn[breed] || breedEn[breed.split(' × ')[0]] || '';
  const desc = breedName || animalType;

  let prompt = `a cute adorable ${desc}, kawaii style, fluffy, big expressive eyes, `;
  prompt += `soft warm lighting, photorealistic, high detail, sitting pose, `;
  prompt += `centered, clean white background, 4k quality`;

  if (features) {
    prompt += `, ${features}`;
  }

  return prompt;
}

/**
 * 使用 Pollinations.ai 免费 API 生成宠物图片
 * 无需 API key，直接 GET 请求返回图片
 */
export function generatePetImageUrl(prompt: string, width: number = 512, height: number = 512): string {
  const encoded = encodeURIComponent(prompt);
  const seed = Math.floor(Math.random() * 1000000);
  return `https://image.pollinations.ai/prompt/${encoded}?width=${width}&height=${height}&model=flux&nologo=true&seed=${seed}`;
}

/**
 * 将网络图片 URL 转换为 base64 存储（用于离线使用）
 */
export async function imageUrlToBase64(url: string): Promise<string> {
  try {
    const response = await fetch(url);
    const blob = await response.blob();
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result as string);
      reader.onerror = () => resolve(url);
      reader.readAsDataURL(blob);
    });
  } catch {
    return url;
  }
}
