import { useEffect, useState, useRef } from 'react';

interface BubbleProps {
  content: string;
  isUser?: boolean;
  typing?: boolean;
  onTypingComplete?: () => void;
  /** 宠物名字（用于消息发送者显示，默认"小宝贝"） */
  petName?: string;
}

/**
 * 对话气泡组件
 * 支持打字机效果显示宠物消息
 */
export default function Bubble({ content, isUser, typing = false, onTypingComplete, petName }: BubbleProps) {
  const [displayText, setDisplayText] = useState(isUser ? content : '');
  const [isTyping, setIsTyping] = useState(!isUser && typing);
  const bubbleRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isUser) {
      setDisplayText(content);
      return;
    }
    if (!typing) {
      setDisplayText(content);
      return;
    }

    setDisplayText('');
    setIsTyping(true);
    let i = 0;
    const timer = setInterval(() => {
      if (i < content.length) {
        setDisplayText(content.substring(0, i + 1));
        i++;
      } else {
        clearInterval(timer);
        setIsTyping(false);
        onTypingComplete?.();
      }
    }, 40 + Math.random() * 30);

    return () => clearInterval(timer);
  }, [content, isUser, typing, onTypingComplete]);

  // 自动滚动到底部
  useEffect(() => {
    if (bubbleRef.current) {
      bubbleRef.current.scrollIntoView({ behavior: 'smooth', block: 'end' });
    }
  }, [displayText]);

  return (
    <div ref={bubbleRef} className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
      <div
        className={`max-w-[75%] px-4 py-3 rounded-2xl text-sm leading-relaxed ${
          isUser
            ? 'bg-gradient-to-br from-[#c4a48a] to-[#a08070] text-white rounded-br-md'
            : 'bg-white/80 backdrop-blur text-[#5a4a3a] rounded-bl-md shadow-sm border border-[#e0d0c0]/50'
        }`}
      >
        {!isUser && (
          <div className="flex items-center gap-1 mb-1">
            <span className="text-xs">🐾</span>
            <span className="text-xs text-[#a08c7a]">{petName || '小宝贝'}</span>
          </div>
        )}
        <span className={isTyping ? 'typewriter' : ''}>{displayText}</span>
        {isTyping && <span className="inline-block w-1 h-4 bg-[#c4a48a] ml-0.5 animate-pulse align-middle" />}
      </div>
    </div>
  );
}
