import { useState, useRef, useCallback } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Home, Sparkles, BookHeart } from 'lucide-react';

/** 进入管理后台所需的连续点击次数 */
const ADMIN_CLICK_COUNT = 5;

/**
 * 响应式导航栏组件
 * 移动端：底部胶囊悬浮导航
 * 桌面端（md+）：顶部横向导航栏，与标题栏并排
 * 隐藏功能：连续点击"功能"按钮5次进入管理后台
 */
export default function NavBar() {
  const navigate = useNavigate();
  const location = useLocation();
  /** 功能按钮连续点击计数 */
  const featureClickCount = useRef(0);
  /** 计数重置定时器 */
  const resetTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  /** 点击反馈提示 */
  const [hint, setHint] = useState('');

  const tabs = [
    { path: '/home', icon: Home, label: '陪伴' },
    { path: '/features', icon: Sparkles, label: '功能' },
    { path: '/memory', icon: BookHeart, label: '记忆' },
  ];

  /**
   * 判断当前 tab 是否激活
   */
  const isTabActive = (path: string) => {
    return location.pathname === path ||
      (path !== '/home' && location.pathname.startsWith(path));
  };

  /**
   * 处理"功能"按钮点击：正常导航 + 连续5次进入管理后台
   * 1.5秒内未达到5次则重置计数
   */
  const handleFeatureClick = useCallback(() => {
    featureClickCount.current += 1;

    // 清除之前的重置定时器
    if (resetTimer.current) clearTimeout(resetTimer.current);

    if (featureClickCount.current >= ADMIN_CLICK_COUNT) {
      // 达到5次，进入管理后台（不再跳转 /features，避免跳闪）
      featureClickCount.current = 0;
      setHint('');
      navigate('/admin');
    } else {
      // 显示进度提示（从第2次开始显示）
      if (featureClickCount.current >= 2) {
        setHint(`再点击 ${ADMIN_CLICK_COUNT - featureClickCount.current} 次进入管理后台`);
      }
      // 正常导航到功能页（仅在未达到5次时跳转）
      navigate('/features');
      // 1.5秒后重置计数
      resetTimer.current = setTimeout(() => {
        featureClickCount.current = 0;
        setHint('');
      }, 1500);
    }
  }, [navigate]);

  return (
    <>
      {/* 桌面端顶部横向导航栏 */}
      <nav className="hidden md:flex fixed top-9 left-0 right-0 h-12 items-center justify-center gap-2 z-[9998] bg-[#fef3e8]/60 backdrop-blur-sm border-b border-[#e0d0c0]/30">
        {tabs.map(tab => {
          const isActive = isTabActive(tab.path);
          const Icon = tab.icon;
          /** 功能按钮使用专用点击处理器（连续5次进入管理后台） */
          const onClick = tab.path === '/features' ? handleFeatureClick : () => navigate(tab.path);
          return (
            <button
              key={tab.path}
              onClick={onClick}
              className={`flex items-center gap-2 px-5 py-1.5 rounded-full transition-all duration-300 ${
                isActive
                  ? 'bg-gradient-to-br from-[#c4a48a] to-[#a08070] text-white shadow-md shadow-[0_0_12px_rgba(196,164,138,0.4)]'
                  : 'text-[#8b6f5e] hover:bg-[#c4a48a]/10'
              }`}
            >
              <Icon size={16} />
              <span className="text-sm font-medium">{tab.label}</span>
            </button>
          );
        })}
        <div className="absolute bottom-0 left-0 right-0 h-px glow-line" />
      </nav>

      {/* 移动端底部胶囊导航 */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 z-50 flex justify-center pb-4 pointer-events-none">
        <div className="flex items-center gap-1 bg-white/70 backdrop-blur-xl rounded-full px-2 py-2 shadow-lg border border-white/50 pointer-events-auto glow-border">
          {tabs.map(tab => {
            const isActive = isTabActive(tab.path);
            const Icon = tab.icon;
            /** 功能按钮使用专用点击处理器 */
            const onClick = tab.path === '/features' ? handleFeatureClick : () => navigate(tab.path);
            return (
              <button
                key={tab.path}
                onClick={onClick}
                className={`flex flex-col items-center gap-0.5 px-4 py-2 rounded-full transition-all duration-300 ${
                  isActive
                    ? 'bg-gradient-to-br from-[#c4a48a] to-[#a08070] text-white shadow-md shadow-[0_0_12px_rgba(196,164,138,0.4)]'
                    : 'text-[#8b6f5e] hover:bg-[#c4a48a]/10'
                }`}
              >
                <Icon size={20} />
                <span className="text-xs">{tab.label}</span>
              </button>
            );
          })}
        </div>
        {/* 连续点击进度提示 */}
        {hint && (
          <div className="absolute -top-8 left-1/2 -translate-x-1/2 bg-[#5a4a3a]/90 text-white text-xs px-3 py-1 rounded-full whitespace-nowrap animate-fadeIn">
            {hint}
          </div>
        )}
      </div>
    </>
  );
}
