import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { generateId, randomPick } from '@/utils/helpers';
import type { EmotionType } from '@/utils/emotionAnalyzer';
import { presetDiaries } from '@/data/diaries';

export interface Pet {
  id: string;
  name: string;
  species: string;
  breed: string;
  personality: string[];
  features: string;
  photoData?: string;
  imageUrl?: string;
  mood: number;
  intimacy: number;
  interactCount: number;
  createdAt: string;
  lastActiveDate: string;
  currentAction: 'idle' | 'breathe' | 'happy' | 'sleep' | 'snuggle' | 'jump' | 'lick' | 'wag';
  /** 上次访问时间戳（ISO字符串），用于时间感知系统 */
  lastVisitTime?: string;
  /** 连续访问天数 */
  visitStreak?: number;
  /** 宠物生日（YYYY-MM-DD 格式，可选） */
  birthday?: string;
  /** 宠物离世日期（YYYY-MM-DD 格式，可选，用于彩虹桥纪念日） */
  passingDate?: string;
  /** 上次触发纪念日的日期（用于避免同一天重复触发） */
  lastAnniversaryTriggered?: string;
}

export interface Message {
  id: string;
  role: 'user' | 'pet';
  content: string;
  emotion?: EmotionType | 'happy' | 'sad' | 'calm' | 'excited' | 'sleepy';
  timestamp: string;
}

export interface DiaryEntry {
  id: string;
  date: string;
  content: string;
  weather: string;
  mood: string;
}

export interface Postcard {
  id: string;
  userMessage: string;
  petReply: string;
  createdAt: string;
}

interface PetStore {
  pet: Pet | null;
  messages: Message[];
  diaries: DiaryEntry[];
  postcards: Postcard[];
  remindersEnabled: boolean;
  currentPage: string;
  hasOnboarded: boolean;

  createPet: (data: Omit<Pet, 'id' | 'mood' | 'intimacy' | 'interactCount' | 'createdAt' | 'lastActiveDate' | 'currentAction'>) => void;
  addMessage: (msg: Omit<Message, 'id' | 'timestamp'>) => void;
  interact: (type: 'head' | 'body' | 'feed' | 'talk') => string;
  setPetAction: (action: Pet['currentAction']) => void;
  updateMood: (delta: number) => void;
  updateIntimacy: (delta: number) => void;
  /** 更新宠物形象图片（用于重新生成） */
  updatePetImage: (imageUrl: string) => void;
  addDiary: (diary: Omit<DiaryEntry, 'id'>) => void;
  addPostcard: (postcard: Omit<Postcard, 'id' | 'createdAt'>) => void;
  setRemindersEnabled: (enabled: boolean) => void;
  setCurrentPage: (page: string) => void;
  setHasOnboarded: (v: boolean) => void;
  resetPet: () => void;
  /** 记录用户访问，计算间隔并执行心情衰减，返回迎接信息 */
  recordVisit: () => { intervalHours: number; greeting: string; petEmotion: string };
}

export const usePetStore = create<PetStore>()(
  persist(
    (set, get) => ({
      pet: null,
      messages: [],
      diaries: presetDiaries,
      postcards: [],
      remindersEnabled: true,
      currentPage: 'home',
      hasOnboarded: false,

      createPet: (data) => {
        const pet: Pet = {
          id: generateId(),
          ...data,
          mood: 70,
          intimacy: 30,
          interactCount: 0,
          createdAt: new Date().toISOString(),
          lastActiveDate: new Date().toDateString(),
          currentAction: 'breathe',
        };
        set({
          pet,
          hasOnboarded: true,
          messages: [{
          id: generateId(),
          role: 'pet',
          content: `（慢慢睁开眼睛，看着你）${data.name}…是你吗？我好像…做了一个很长的梦…`,
          emotion: 'calm',
          timestamp: new Date().toISOString(),
        }],
        });
      },

      addMessage: (msg) => {
        const newMsg: Message = {
          ...msg,
          id: generateId(),
          timestamp: new Date().toISOString(),
        };
        set(state => ({
          messages: [...state.messages, newMsg],
        }));
      },

      interact: (type) => {
        const pet = get().pet;
        if (!pet) return '';

        let reply = '';
        let action: Pet['currentAction'] = 'happy';
        let moodDelta = 5;
        let intimacyDelta = 3;

        switch (type) {
          case 'head':
            action = 'snuggle';
            reply = randomPick([
              '（舒服地眯起眼睛）呼噜呼噜～',
              '把头蹭到你手心里～',
              '耳朵往后一倒，享受摸头！',
              '好舒服…再用力一点点…',
            ]);
            moodDelta = 8; intimacyDelta = 5;
            break;
          case 'body':
            action = 'wag';
            reply = randomPick([
              '（尾巴快速摇摆）好痒好痒！',
              '翻过身露出肚子！摸摸这里！',
              '嘿嘿嘿…那里是痒痒肉啦！',
              '被你摸得好舒服呀～',
            ]);
            moodDelta = 6; intimacyDelta = 4;
            break;
          case 'feed':
            action = 'happy';
            reply = randomPick([
              '！！！有吃的！！！扑上去！',
              '（大口大口）好吃好吃！谢谢主人！',
              '舔舔嘴巴…还有吗？',
              '吃得饱饱的！要在主人身边睡觉！',
            ]);
            moodDelta = 10; intimacyDelta = 6;
            break;
          case 'talk':
            action = 'idle';
            reply = randomPick([
              '（歪头听你说话）嗯嗯！我在听呢～',
              '（认真地看着你）然后呢然后呢？',
              '呼噜呼噜…你说什么都好，我都听。',
            ]);
            moodDelta = 3; intimacyDelta = 2;
            break;
        }

        set(state => ({
          pet: state.pet ? {
            ...state.pet,
            mood: Math.min(100, state.pet.mood + moodDelta),
            intimacy: Math.min(100, state.pet.intimacy + intimacyDelta),
            interactCount: state.pet.interactCount + 1,
            currentAction: action,
          } : null,
        }));

        setTimeout(() => {
          set(state => ({
            pet: state.pet ? { ...state.pet, currentAction: 'breathe' } : null,
          }));
        }, 2000);

        return reply;
      },

      setPetAction: (action) => {
        set(state => ({
          pet: state.pet ? { ...state.pet, currentAction: action } : null,
        }));
      },

      updateMood: (delta) => {
        set(state => ({
          pet: state.pet ? {
            ...state.pet,
            mood: Math.max(0, Math.min(100, state.pet.mood + delta)),
          } : null,
        }));
      },

      updateIntimacy: (delta) => {
        set(state => ({
          pet: state.pet ? {
            ...state.pet,
            intimacy: Math.max(0, Math.min(100, state.pet.intimacy + delta)),
          } : null,
        }));
      },

      /** 更新宠物形象图片 */
      updatePetImage: (imageUrl: string) => {
        set(state => ({
          pet: state.pet ? { ...state.pet, imageUrl } : null,
        }));
      },

      addDiary: (diary) => {
        const newDiary: DiaryEntry = { ...diary, id: generateId() };
        set(state => ({
          diaries: [newDiary, ...state.diaries],
        }));
      },

      addPostcard: (postcard) => {
        const newPostcard: Postcard = {
          ...postcard,
          id: generateId(),
          createdAt: new Date().toISOString(),
        };
        set(state => ({
          postcards: [newPostcard, ...state.postcards],
        }));
      },

      setRemindersEnabled: (enabled) => set({ remindersEnabled: enabled }),
      setCurrentPage: (page) => set({ currentPage: page }),
      setHasOnboarded: (v) => set({ hasOnboarded: v }),

      /**
       * 记录用户访问，计算与上次访问的间隔，执行心情自然衰减
       * 根据间隔和当前时段生成宠物迎接语
       * @returns { intervalHours, greeting, petEmotion }
       */
      recordVisit: () => {
        const pet = get().pet;
        if (!pet) return { intervalHours: 0, greeting: '', petEmotion: 'breathe' };

        const now = new Date();
        const lastVisit = pet.lastVisitTime ? new Date(pet.lastVisitTime) : null;
        const intervalHours = lastVisit
          ? (now.getTime() - lastVisit.getTime()) / (1000 * 60 * 60)
          : 0;

        // 心情自然衰减：每小时衰减 1 点（最低 30）
        let moodDelta = 0;
        if (intervalHours > 1) {
          moodDelta = -Math.min(Math.floor(intervalHours), 30);
        }

        // 连续访问天数计算
        let streak = pet.visitStreak || 0;
        if (lastVisit) {
          const lastDate = lastVisit.toDateString();
          const todayDate = now.toDateString();
          const yesterday = new Date(now);
          yesterday.setDate(yesterday.getDate() - 1);
          if (lastDate === yesterday.toDateString()) {
            streak += 1; // 昨天来过，连续+1
          } else if (lastDate !== todayDate) {
            streak = 1; // 非昨天非今天，重置为1
          }
          // 今天已来过则不增加
        } else {
          streak = 1;
        }

        // 生成迎接语
        const hour = now.getHours();
        let greeting = '';
        let petEmotion = 'breathe';

        if (!lastVisit) {
          // 首次访问
          greeting = `${pet.name} 一直在这里等你`;
          petEmotion = 'happy';
        } else if (intervalHours < 0.1) {
          // 刚刚来过
          greeting = `${pet.name} 还没反应过来你又来啦`;
          petEmotion = 'happy';
        } else if (intervalHours < 3) {
          greeting = `${pet.name} 刚才还在想你呢`;
          petEmotion = 'happy';
        } else if (intervalHours < 12) {
          greeting = `${pet.name} 等你好一会儿了`;
          petEmotion = 'snuggle';
        } else if (intervalHours < 48) {
          greeting = `${pet.name} 好想你，终于等到你了`;
          petEmotion = 'snuggle';
        } else if (intervalHours < 168) {
          greeting = `${pet.name} 以为你不来了…你回来了！`;
          petEmotion = 'jump';
        } else {
          greeting = `${pet.name} 一直在等你回来`;
          petEmotion = 'snuggle';
        }

        // 时段问候叠加
        if (hour >= 5 && hour < 11) {
          greeting = `早安～${greeting}`;
        } else if (hour >= 11 && hour < 14) {
          greeting = `中午好～${greeting}`;
        } else if (hour >= 14 && hour < 18) {
          greeting = `下午好～${greeting}`;
        } else if (hour >= 18 && hour < 23) {
          greeting = `晚上好～${greeting}`;
        } else {
          greeting = `夜深了～${greeting}`;
        }

        // 更新宠物状态
        set(state => ({
          pet: state.pet ? {
            ...state.pet,
            mood: Math.max(30, state.pet.mood + moodDelta),
            lastVisitTime: now.toISOString(),
            visitStreak: streak,
            lastActiveDate: now.toDateString(),
          } : null,
        }));

        return { intervalHours, greeting, petEmotion };
      },

      resetPet: () => {
        set({
          pet: null,
          messages: [],
          diaries: presetDiaries,
          postcards: [],
          hasOnboarded: false,
          currentPage: 'welcome',
        });
        localStorage.removeItem('pet-store');
      },
    }),
    {
      name: 'pet-store',
    }
  )
);
