import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Send } from 'lucide-react';
import { usePetStore } from '@/store/usePetStore';
import PetAvatar from '@/components/PetAvatar';
import { analyzeEmotion, getPetReaction } from '@/utils/emotionAnalyzer';


/**
 * 情绪共感页面
 * 用户输入今天的心情，AI分析情绪，宠物做出对应反应
 */
export default function MoodSense() {
  const navigate = useNavigate();
  const pet = usePetStore(s => s.pet);
  const addMessage = usePetStore(s => s.addMessage);
  const updateMood = usePetStore(s => s.updateMood);
  const setPetAction = usePetStore(s => s.setPetAction);

  const [input, setInput] = useState('');
  const [analyzed, setAnalyzed] = useState(false);
  const [petReaction, setPetReaction] = useState<{ action: string; reply: string; petEmotion: string } | null>(null);
  const [emotionLabel, setEmotionLabel] = useState('');
  const [emotionColor, setEmotionColor] = useState('#c4a48a');

  const emotionLabels: Record<string, { label: string; color: string }> = {
    happy: { label: '😊 开心', color: '#f0c27f' },
    sad: { label: '🥺 难过', color: '#a0b8d8' },
    angry: { label: '😤 生气', color: '#e88a8a' },
    anxious: { label: '😰 焦虑', color: '#d4a574' },
    tired: { label: '😴 疲惫', color: '#b0c4de' },
    neutral: { label: '😌 平静', color: '#c4a48a' },
  };

  const handleAnalyze = () => {
    const text = input.trim();
    if (!text) return;

    const result = analyzeEmotion(text);
    const reaction = getPetReaction(result.emotion);

    const label = emotionLabels[result.emotion] || emotionLabels.neutral;
    setEmotionLabel(label.label);
    setEmotionColor(label.color);
    setPetReaction(reaction);
    setAnalyzed(true);

    // 宠物回应
    const actionMap: Record<string, 'idle' | 'breathe' | 'happy' | 'sleep' | 'snuggle' | 'jump' | 'lick' | 'wag'> = {
      excited: 'jump',
      calm: 'idle',
      sleepy: 'sleep',
      happy: 'happy',
      sad: 'snuggle',
    };
    setPetAction(actionMap[reaction.petEmotion] || 'idle');
    addMessage({ role: 'pet', content: reaction.reply });

    // 根据情绪调整心情值
    if (result.emotion === 'happy') updateMood(5);
    else if (['sad', 'anxious', 'angry', 'tired'].includes(result.emotion)) updateMood(-3);

    setTimeout(() => setPetAction('breathe'), 5000);
  };

  const quickPrompts = [
    '今天好开心！',
    '有点难过...',
    '工作好累啊',
    '今天好焦虑',
    '一切都很顺利',
  ];

  return (
    <div className="min-h-screen pb-8">
      {/* 顶部 */}
      <div className="sticky top-9 z-10 flex items-center px-4 py-3 bg-gradient-to-b from-[#fdf6f0] to-transparent">
        <button onClick={() => navigate('/features')} className="w-10 h-10 flex items-center justify-center rounded-full bg-white/60 backdrop-blur text-[#8b6f5e] hover:bg-white/80">
          <ArrowLeft size={20} />
        </button>
        <h1 className="flex-1 text-center text-lg font-medium text-[#5a4a3a] mr-10" style={{ fontFamily: 'Georgia, serif' }}>
          💗 情绪共感
        </h1>
      </div>

      <div className="px-6 max-w-md mx-auto">
        {/* 描述 */}
        <p className="text-center text-sm text-[#a08c7a] mb-6">
          说说你今天怎么样，{pet?.name || '它'}会感觉到的
        </p>

        {/* 宠物展示 */}
        <div className="flex justify-center mb-6">
          <div className="relative">
            <PetAvatar
              pet={pet!}
              size={220}
              emotion={petReaction?.petEmotion || 'breathe'}
            />
            {analyzed && (
              <div
                className="absolute -top-2 -right-2 px-3 py-1 rounded-full text-white text-xs font-medium shadow-md animate-fadeIn"
                style={{ background: emotionColor }}
              >
                {emotionLabel}
              </div>
            )}
          </div>
        </div>

        {/* 宠物回应 */}
        {analyzed && petReaction && (
          <div className="bg-white/60 backdrop-blur rounded-2xl p-4 mb-6 border border-[#e0d0c0]/50 animate-fadeIn">
            <div className="flex items-center gap-2 mb-2">
              <span>🐾</span>
              <span className="text-sm text-[#8b6f5e] font-medium">{pet?.name || '它'}说：</span>
            </div>
            <p className="text-[#5a4a3a] leading-relaxed text-sm pl-6">{petReaction.reply}</p>
          </div>
        )}

        {/* 输入区 */}
        {!analyzed && (
          <>
            <div className="space-y-2 mb-4">
              {quickPrompts.map((p, i) => (
                <button
                  key={i}
                  onClick={() => setInput(p)}
                  className="w-full text-left px-4 py-2.5 bg-white/50 hover:bg-white/80 rounded-xl text-sm text-[#8b6f5e] border border-[#e0d0c0]/40 transition-all hover:border-[#c4a48a]/40"
                >
                  {p}
                </button>
              ))}
            </div>

            <div className="flex gap-2 bg-white/70 backdrop-blur rounded-full px-4 py-2 shadow-sm border border-white/50">
              <input
                type="text"
                value={input}
                onChange={e => setInput(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleAnalyze()}
                placeholder="今天过得怎么样？"
                className="flex-1 bg-transparent text-sm text-[#5a4a3a] placeholder-[#c4b4a4] outline-none py-1"
              />
              <button
                onClick={handleAnalyze}
                disabled={!input.trim()}
                className={`w-8 h-8 flex items-center justify-center rounded-full transition-all ${
                  input.trim() ? 'bg-gradient-to-br from-[#e8a0a0] to-[#d48080] text-white' : 'bg-[#e0d0c0] text-[#a09080]'
                }`}
              >
                <Send size={14} />
              </button>
            </div>
          </>
        )}

        {/* 再试一次 */}
        {analyzed && (
          <button
            onClick={() => { setAnalyzed(false); setPetReaction(null); setInput(''); }}
            className="w-full warm-btn mt-4"
          >
            再和它说说
          </button>
        )}
      </div>
    </div>
  );
}
