import { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Send, Utensils, MessageCircle, RefreshCw, Mic, Volume2, VolumeX } from 'lucide-react';
import { usePetStore } from '@/store/usePetStore';
import PetAvatar from '@/components/PetAvatar';
import Bubble from '@/components/Bubble';
import StatusBar from '@/components/StatusBar';
import NavBar from '@/components/NavBar';
import ParticleBackground from '@/components/ParticleBackground';
import { randomPick } from '@/utils/helpers';
import { headPatReplies, feedReplies, happyReplies, sadReplies, calmReplies, excitedReplies, sleepyReplies } from '@/data/replies';
import { analyzeEmotion, getPetReaction } from '@/utils/emotionAnalyzer';
import { initTTS, speak, cancelSpeak, startListening, stopListening, isTTSSupported, isSTTSupported } from '@/utils/speech';
import { checkAnniversary, getAnniversaryAmbience, AnniversaryResult } from '@/utils/anniversary';

/**
 * 获取当前时段模式
 * @returns 'day' | 'night'，用于昼夜场景氛围切换
 */
function getTimeMode(): 'day' | 'night' {
  const hour = new Date().getHours();
  return (hour >= 6 && hour < 19) ? 'day' : 'night';
}

/** Electron API 类型声明（含 AI 深度对话、日记、梦境） */
interface ChatAPI {
  chatWithPet: (params: {
    messages: Array<{ role: 'user' | 'pet'; content: string }>;
    petInfo: { name: string; species: string; breed: string; personality: string[]; features: string };
    userEmotion?: string;
  }) => Promise<{ success: boolean; reply?: string; error?: string }>;
  /** AI 自动日记生成 */
  generateDiary: (params: {
    messages: Array<{ role: 'user' | 'pet'; content: string }>;
    petInfo: { name: string; species: string; breed: string; personality: string[] };
    diaryDate: string;
  }) => Promise<{ success: boolean; content?: string; error?: string }>;
  /** AI 梦境故事生成 */
  generateDreamStory: (params: {
    petInfo: { name: string; species: string; breed: string; personality: string[] };
    intervalHours: number;
  }) => Promise<{ success: boolean; content?: string; error?: string }>;
}

/** 获取 Electron 对话 API */
function getChatAPI(): ChatAPI | null {
  return (window as Window & { electronAPI?: ChatAPI }).electronAPI ?? null;
}

/**
 * 互动主界面
 * 宠物展示、触摸互动、AI对话、状态面板
 */
export default function Home() {
  const navigate = useNavigate();
  const pet = usePetStore(s => s.pet);
  const messages = usePetStore(s => s.messages);
  const addMessage = usePetStore(s => s.addMessage);
  const addDiary = usePetStore(s => s.addDiary);
  const interact = usePetStore(s => s.interact);
  const setPetAction = usePetStore(s => s.setPetAction);
  const recordVisit = usePetStore(s => s.recordVisit);

  const [inputText, setInputText] = useState('');
  const [petEmotion, setPetEmotion] = useState<'happy' | 'sad' | 'calm' | 'excited' | 'sleepy' | 'snuggle' | 'jump' | 'breathe' | 'wag' | 'sleep' | 'idle' | 'lick'>('breathe');
  const [isPetTyping, setIsPetTyping] = useState(false);
  const [bubbleText, setBubbleText] = useState('');
  const [showBubble, setShowBubble] = useState(false);
  const [showRegenerateConfirm, setShowRegenerateConfirm] = useState(false);
  /** 顶部迎接语（时间感知系统） */
  const [greeting, setGreeting] = useState('');
  /** 语音播报开关（TTS），默认开启 */
  const [voiceEnabled, setVoiceEnabled] = useState(true);
  /** 是否正在语音输入（STT监听中） */
  const [isListening, setIsListening] = useState(false);
  /** 语音识别中间结果（实时显示） */
  const [interimText, setInterimText] = useState('');
  /** 纪念日检测结果（生日/彩虹桥纪念日） */
  const [anniversary, setAnniversary] = useState<AnniversaryResult | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);
  /** 语音开关状态用 ref 保持最新值，避免闭包陈旧引用 */
  const voiceEnabledRef = useRef(voiceEnabled);
  useEffect(() => { voiceEnabledRef.current = voiceEnabled; }, [voiceEnabled]);

  useEffect(() => {
    if (!pet) {
      navigate('/', { replace: true });
      return;
    }
    // 记录访问，获取时间感知迎接语
    const result = recordVisit();

    // 纪念日检测：优先级高于时间感知迎接语
    const anniversaryResult = checkAnniversary(pet.birthday, pet.passingDate, pet.name);
    if (anniversaryResult.type !== 'none') {
      setAnniversary(anniversaryResult);
      // 纪念日问候优先显示
      setGreeting(anniversaryResult.greeting);
      setPetEmotion(anniversaryResult.petEmotion as typeof petEmotion);
      setBubbleText(anniversaryResult.greeting);
      setShowBubble(true);
      addMessage({ role: 'pet', content: anniversaryResult.greeting });
      // 语音播报纪念日问候
      if (voiceEnabledRef.current && isTTSSupported()) {
        speak(anniversaryResult.greeting);
      }
      setTimeout(() => {
        setShowBubble(false);
        setPetEmotion('breathe');
        setPetAction('breathe');
      }, 6000); // 纪念日问候显示更久
    } else if (result.greeting) {
      setGreeting(result.greeting);
      setPetEmotion(result.petEmotion as typeof petEmotion);
      // 显示迎接气泡
      setBubbleText(result.greeting);
      setShowBubble(true);
      addMessage({ role: 'pet', content: result.greeting });
      // 语音播报迎接语（若开启语音且支持TTS）
      if (voiceEnabledRef.current && isTTSSupported()) {
        speak(result.greeting);
      }
      setTimeout(() => {
        setShowBubble(false);
        setPetEmotion('breathe');
        setPetAction('breathe');
      }, 4000);
    }

    /**
     * AI 自动日记生成：跨天时（间隔>=24小时），生成昨日日记
     * 异步执行，不阻塞UI。基于昨日对话内容生成宠物视角日记
     */
    if (result.intervalHours >= 24) {
      const chatAPI = getChatAPI();
      if (chatAPI && messages.length > 0) {
        // 计算昨天的日期字符串
        const yesterday = new Date();
        yesterday.setDate(yesterday.getDate() - 1);
        const yesterdayStr = `${yesterday.getFullYear()}-${String(yesterday.getMonth() + 1).padStart(2, '0')}-${String(yesterday.getDate()).padStart(2, '0')}`;

        // 异步生成日记，不阻塞主流程
        (async () => {
          try {
            const diaryResult = await chatAPI.generateDiary({
              messages: messages.slice(-20).map(m => ({
                role: m.role as 'user' | 'pet',
                content: m.content,
              })),
              petInfo: {
                name: pet.name,
                species: pet.species,
                breed: pet.breed,
                personality: pet.personality,
              },
              diaryDate: yesterdayStr,
            });
            if (diaryResult.success && diaryResult.content) {
              addDiary({
                date: yesterdayStr,
                content: diaryResult.content,
                weather: '晴天',
                mood: '温暖',
              });
              console.log('已生成昨日日记:', yesterdayStr);
            }
          } catch (err) {
            console.warn('日记生成失败:', err);
          }
        })();
      }
    }

    /**
     * 梦境叙事系统：长时间未访问（>=6小时），触发梦境故事
     * 宠物从梦中"惊醒"，讲述梦境内容
     */
    if (result.intervalHours >= 6) {
      const chatAPI = getChatAPI();
      if (chatAPI) {
        // 异步生成梦境故事
        (async () => {
          try {
            const dreamResult = await chatAPI.generateDreamStory({
              petInfo: {
                name: pet.name,
                species: pet.species,
                breed: pet.breed,
                personality: pet.personality,
              },
              intervalHours: result.intervalHours,
            });
            if (dreamResult.success && dreamResult.content) {
              // 延迟显示梦境故事（在迎接语之后）
              setTimeout(() => {
                setBubbleText(dreamResult.content);
                setShowBubble(true);
                setPetEmotion('snuggle');
                addMessage({ role: 'pet', content: dreamResult.content });
                if (voiceEnabledRef.current && isTTSSupported()) {
                  speak(dreamResult.content);
                }
                setTimeout(() => {
                  setShowBubble(false);
                  setPetEmotion('breathe');
                  setPetAction('breathe');
                }, 5000);
              }, 5000); // 迎接语显示5秒后显示梦境
            }
          } catch (err) {
            console.warn('梦境生成失败:', err);
          }
        })();
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 自动滚动到最新消息（仅滚动聊天容器内部，避免整页跳动）
  useEffect(() => {
    const container = chatContainerRef.current;
    if (container) {
      container.scrollTo({ top: container.scrollHeight, behavior: 'smooth' });
    }
    // 移动端容器（通过 messagesEndRef 兜底）
    const mobileEnd = messagesEndRef.current;
    if (mobileEnd && mobileEnd.parentElement) {
      mobileEnd.parentElement.scrollTop = mobileEnd.parentElement.scrollHeight;
    }
  }, [messages]);

  /**
   * 语音陪伴系统初始化
   * 加载 TTS 中文语音列表，组件卸载时清理语音资源
   */
  useEffect(() => {
    initTTS();
    return () => {
      cancelSpeak();
      stopListening();
    };
  }, []);

  if (!pet) return null;

  /** 触摸宠物 */
  const handlePat = (part: 'head' | 'body' | 'paw') => {
    const reply = interact(part === 'head' ? 'head' : part === 'body' ? 'body' : 'feed');
    showPetBubble(reply, part === 'head' ? 'snuggle' : part === 'body' ? 'wag' : 'happy');
  };

  /** 喂食 */
  const handleFeed = () => {
    const reply = interact('feed');
    showPetBubble(reply, 'happy');
  };

  /** 显示宠物气泡，3秒后自动隐藏气泡并恢复待机状态。同时语音播报（若开启） */
  const showPetBubble = (text: string, emotion: 'happy' | 'sad' | 'calm' | 'excited' | 'sleepy' | 'snuggle' | 'jump' | 'breathe' | 'wag' | 'sleep' | 'idle' | 'lick') => {
    setBubbleText(text);
    setPetEmotion(emotion);
    setShowBubble(true);
    addMessage({ role: 'pet', content: text });
    // 语音播报宠物回复
    if (voiceEnabledRef.current && isTTSSupported()) {
      speak(text);
    }
    // 3秒后隐藏气泡并恢复待机呼吸状态
    setTimeout(() => {
      setShowBubble(false);
      setPetEmotion('breathe');
      setPetAction('breathe');
    }, 3000);
  };

  /** 发送消息：优先调用 AI 大模型，失败回退关键词系统 */
  const handleSend = async () => {
    const text = inputText.trim();
    if (!text || isPetTyping) return;

    addMessage({ role: 'user', content: text });
    setInputText('');
    setIsPetTyping(true);

    // 情绪分析（用于调整 AI 回复语气 + 回退系统）
    const { emotion } = analyzeEmotion(text);
    const reaction = getPetReaction(emotion);

    /** 关键词系统回退回复 */
    const fallbackReply = (): string => {
      if (emotion === 'happy') return randomPick(happyReplies);
      if (emotion === 'sad') return randomPick(sadReplies);
      if (emotion === 'angry' || emotion === 'anxious') return reaction.reply;
      if (emotion === 'tired') return randomPick(sleepyReplies);
      if (text.includes('摸') || text.includes('头') || text.includes('抱')) return randomPick(headPatReplies);
      if (text.includes('吃') || text.includes('饿') || text.includes('饭')) return randomPick(feedReplies);
      if (text.includes('玩') || text.includes('出去') || text.includes('遛')) return randomPick(excitedReplies);
      if (text.includes('睡') || text.includes('困') || text.includes('晚安')) return randomPick(sleepyReplies);
      return randomPick(calmReplies);
    };

    /** 显示回复并恢复待机。同时语音播报（若开启） */
    const showReply = (reply: string, petEmotion: string) => {
      setIsPetTyping(false);
      setPetEmotion(petEmotion as 'happy' | 'sad' | 'calm' | 'excited' | 'sleepy' | 'snuggle' | 'jump' | 'breathe' | 'wag' | 'sleep' | 'idle' | 'lick');
      addMessage({ role: 'pet', content: reply });
      // 语音播报AI回复
      if (voiceEnabledRef.current && isTTSSupported()) {
        speak(reply);
      }
      setTimeout(() => {
        setPetAction('breathe');
        setPetEmotion('breathe');
      }, 3000);
    };

    // 优先尝试 AI 大模型对话
    const chatAPI = getChatAPI();
    if (chatAPI && pet) {
      try {
        // 取最近10条对话作为上下文记忆
        const recentMessages = messages.slice(-10).map(m => ({
          role: m.role as 'user' | 'pet',
          content: m.content,
        }));
        // 加入当前用户消息
        recentMessages.push({ role: 'user', content: text });

        const result = await chatAPI.chatWithPet({
          messages: recentMessages,
          petInfo: {
            name: pet.name,
            species: pet.species,
            breed: pet.breed,
            personality: pet.personality,
            features: pet.features,
          },
          userEmotion: emotion,
        });

        if (result.success && result.reply) {
          // AI 回复成功，根据情绪设置宠物表情
          const aiPetEmotion =
            emotion === 'happy' ? 'excited' :
            emotion === 'sad' ? 'snuggle' :
            emotion === 'tired' ? 'sleep' :
            'calm';
          showReply(result.reply, aiPetEmotion);
          return;
        }
      } catch (err) {
        console.warn('AI 对话失败，回退关键词系统:', err);
      }
    }

    // 回退：关键词系统（延迟模拟思考）
    setTimeout(() => {
      showReply(fallbackReply(), reaction.petEmotion);
    }, 1000 + Math.random() * 1500);
  };

  /**
   * 重新生成宠物形象
   * 弹出确认对话框，确认后导航到创建页面重新上传照片
   */
  const handleRegenerate = () => {
    setShowRegenerateConfirm(true);
  };

  /** 确认重新生成：跳转到创建页面重新上传照片 */
  const confirmRegenerate = () => {
    setShowRegenerateConfirm(false);
    navigate('/create');
  };

  /**
   * 切换语音播报开关
   * 关闭时停止当前正在播报的语音
   */
  const toggleVoice = () => {
    setVoiceEnabled(prev => {
      const next = !prev;
      if (!next) cancelSpeak();
      return next;
    });
  };

  /**
   * 语音输入处理：点击麦克风开始/停止语音识别
   * 识别完成后自动填入输入框（不自动发送，用户可编辑后发送）
   */
  const handleVoiceInput = () => {
    if (!isSTTSupported()) return;
    if (isListening) {
      stopListening();
      setIsListening(false);
      setInterimText('');
      return;
    }
    setInterimText('');
    setIsListening(true);
    startListening(
      (text, isFinal) => {
        if (isFinal) {
          setInputText(prev => prev ? `${prev}${text}` : text);
          setInterimText('');
        } else {
          setInterimText(text);
        }
      },
      () => {
        setIsListening(false);
        setInterimText('');
      },
      { continuous: false, interimResults: true }
    );
  };

  /** 当前时段模式（昼夜场景） */
  const timeMode = getTimeMode();
  /** 纪念日氛围配置（优先于昼夜场景） */
  const anniversaryAmbience = anniversary ? getAnniversaryAmbience(anniversary) : null;
  /** 粒子强度：纪念日 > 夜间 > 日间 */
  const particleIntensity = anniversaryAmbience?.particleIntensity
    || (timeMode === 'night' ? 'night' : 'normal');

  return (
    <div
      className="min-h-screen flex flex-col pb-36 md:pb-4 pt-20 md:pt-28 relative"
      style={{
        background: anniversaryAmbience?.background
          || (timeMode === 'night'
            ? 'linear-gradient(180deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%)'
            : 'linear-gradient(180deg, #fdf6f0 0%, #f8efe5 100%)'),
      }}
    >
      {/* 情感粒子背景 */}
      <ParticleBackground intensity={particleIntensity} />
      {/* 顶部问候 - 时间感知系统 */}
      <div className="px-6 pb-4 text-center relative z-10">
        {/* 纪念日徽章 */}
        {anniversary && anniversary.type !== 'none' && (
          <div
            className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full mb-2 animate-fadeIn"
            style={{
              background: anniversary.type === 'birthday'
                ? 'linear-gradient(135deg, #ffd966, #ffb84d)'
                : 'linear-gradient(135deg, #9b7fb5, #7a5f9a)',
              color: 'white',
            }}
          >
            <span className="text-xs font-medium">
              {anniversary.type === 'birthday' ? '🎂 生日快乐' : '🌈 彩虹桥纪念日'}
            </span>
            {anniversary.years > 0 && (
              <span className="text-xs opacity-80">· {anniversary.years}周年</span>
            )}
          </div>
        )}
        <p className={`text-sm ${anniversaryAmbience ? 'text-white/60' : timeMode === 'night' ? 'text-white/50' : 'text-[#a08c7a]'}`}>你回来了</p>
        <h1
          className={`text-xl md:text-2xl font-medium mt-1 animate-fadeIn ${anniversaryAmbience ? 'text-white/90' : timeMode === 'night' ? 'text-white/90' : 'text-[#5a4a3a]'}`}
          style={{ fontFamily: 'Georgia, "Noto Serif SC", serif' }}
        >
          {greeting || `${pet.name} 在这里等你`}
        </h1>
      </div>

      {/* 桌面端双栏布局：左侧宠物+状态，右侧聊天 */}
      <div className="flex-1 flex flex-col md:flex-row gap-4 px-4 md:px-8 max-w-5xl mx-auto w-full">
        {/* 左栏：状态条 + 宠物展示 */}
        <div className="flex-1 flex flex-col">
          {/* 状态条 */}
          <div className="mb-4">
            <StatusBar />
          </div>

          {/* 宠物展示区 */}
          <div className="flex-1 flex flex-col items-center justify-center px-6 relative">
            {/* 对话气泡 */}
            {showBubble && (
              <div className="absolute top-4 left-1/2 -translate-x-1/2 animate-fadeIn z-10">
                <div className="bg-white/90 backdrop-blur rounded-2xl rounded-bl-sm px-4 py-2.5 shadow-lg border border-[#e0d0c0]/50 max-w-xs glow-border">
                  <p className="text-sm text-[#5a4a3a]">{bubbleText}</p>
                </div>
                <div className="w-0 h-0 border-l-8 border-r-8 border-t-8 border-l-transparent border-r-transparent border-t-white/90 mx-auto" />
              </div>
            )}

            {/* 宠物 */}
            <div className="relative mt-8">
              <PetAvatar
                pet={pet}
                size={240}
                interactive
                onHeadClick={() => handlePat('head')}
                onBodyClick={() => handlePat('body')}
                onPawClick={() => handlePat('paw')}
                emotion={petEmotion}
              />

              {/* 互动提示文字 + 重新生成按钮 */}
              <div className="text-center mt-4 flex flex-col items-center gap-3">
                <p className="text-xs text-[#b0a090]">摸摸它的头、身体或爪子</p>
                <button
                  onClick={handleRegenerate}
                  className="flex items-center gap-1.5 rounded-full px-4 py-1.5 text-xs transition-all border bg-white/60 backdrop-blur text-[#8b6f5e] hover:bg-white hover:-translate-y-0.5 border-[#e0d0c0]/50 shadow-sm glow-hover"
                >
                  <RefreshCw size={12} />
                  <span>重新生成形象</span>
                </button>
              </div>
            </div>

            {/* 快捷操作 */}
            <div className="flex gap-3 mt-6">
              <button
                onClick={handleFeed}
                className="flex items-center gap-2 bg-white/70 backdrop-blur rounded-full px-5 py-2.5 text-sm text-[#8b6f5e] hover:bg-white shadow-sm border border-[#e0d0c0]/50 transition-all hover:-translate-y-0.5 glow-hover"
              >
                <Utensils size={16} />
                <span>喂点吃的</span>
              </button>
              <button
                onClick={() => { setPetEmotion('happy'); showPetBubble(randomPick(happyReplies), 'happy'); }}
                className="flex items-center gap-2 bg-white/70 backdrop-blur rounded-full px-5 py-2.5 text-sm text-[#8b6f5e] hover:bg-white shadow-sm border border-[#e0d0c0]/50 transition-all hover:-translate-y-0.5 glow-hover"
              >
                <MessageCircle size={16} />
                <span>说说话</span>
              </button>
            </div>
          </div>
        </div>

        {/* 右栏：聊天区（桌面端显示，固定高度，超出滚动） */}
        <div className="hidden md:flex flex-col w-96 gap-3 flex-shrink-0">
          <div
            ref={chatContainerRef}
            className="h-[420px] bg-white/40 backdrop-blur rounded-2xl border border-[#e0d0c0]/30 p-4 overflow-y-auto space-y-3 glow-border"
          >
            {messages.slice(-20).map((msg, idx) => (
              <Bubble
                key={msg.id}
                content={msg.content}
                isUser={msg.role === 'user'}
                petName={pet?.name}
                typing={idx === messages.slice(-20).length - 1 && msg.role === 'pet' && isPetTyping}
              />
            ))}
            {isPetTyping && messages[messages.length - 1]?.role === 'user' && (
              <div className="flex justify-start animate-fadeIn">
                <div className="bg-white/80 backdrop-blur rounded-2xl rounded-bl-sm px-4 py-3 shadow-sm border border-[#e0d0c0]/50">
                  <div className="flex gap-1">
                    <span className="w-2 h-2 bg-[#c4a48a] rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                    <span className="w-2 h-2 bg-[#c4a48a] rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                    <span className="w-2 h-2 bg-[#c4a48a] rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                  </div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* 桌面端输入框 */}
          <div className="flex items-center gap-2 bg-white/80 backdrop-blur-xl rounded-full px-4 py-2 shadow-lg border border-white/50 glow-border">
            {/* 语音开关按钮 */}
            <button
              onClick={toggleVoice}
              title={voiceEnabled ? '关闭语音播报' : '开启语音播报'}
              className={`w-8 h-8 flex items-center justify-center rounded-full transition-all flex-shrink-0 ${
                voiceEnabled
                  ? 'text-[#c4a48a] hover:bg-[#c4a48a]/10'
                  : 'text-[#c4b4a4] opacity-50'
              }`}
            >
              {voiceEnabled ? <Volume2 size={16} /> : <VolumeX size={16} />}
            </button>
            <input
              type="text"
              value={isListening ? interimText : inputText}
              onChange={e => { if (!isListening) setInputText(e.target.value); }}
              onKeyDown={e => e.key === 'Enter' && !isListening && handleSend()}
              placeholder={isListening ? '正在聆听...' : `和${pet.name}说说话...`}
              className={`flex-1 bg-transparent text-sm placeholder-[#c4b4a4] outline-none py-1 ${isListening ? 'text-[#c4a48a]' : 'text-[#5a4a3a]'}`}
            />
            {/* 语音输入麦克风按钮 */}
            {isSTTSupported() && (
              <button
                onClick={handleVoiceInput}
                title={isListening ? '停止语音输入' : '语音输入'}
                className={`w-8 h-8 flex items-center justify-center rounded-full transition-all flex-shrink-0 ${
                  isListening
                    ? 'bg-[#e88a8a] text-white animate-pulse shadow-md'
                    : 'text-[#8b6f5e] hover:bg-[#c4a48a]/10'
                }`}
              >
                <Mic size={14} />
              </button>
            )}
            <button
              onClick={handleSend}
              disabled={!inputText.trim() || isPetTyping || isListening}
              className={`w-8 h-8 flex items-center justify-center rounded-full transition-all ${
                inputText.trim() && !isPetTyping && !isListening
                  ? 'bg-gradient-to-br from-[#c4a48a] to-[#a08070] text-white shadow-md'
                  : 'bg-[#e0d0c0] text-[#a09080]'
              }`}
            >
              <Send size={14} />
            </button>
          </div>
        </div>
      </div>

      {/* 移动端聊天区（固定高度，超出滚动） */}
      <div className="md:hidden px-4 mt-4">
        <div
          className="h-52 bg-white/40 backdrop-blur rounded-2xl border border-[#e0d0c0]/30 p-4 overflow-y-auto space-y-3 glow-border"
        >
          {messages.slice(-6).map((msg, idx) => (
            <Bubble
              key={msg.id}
              content={msg.content}
              isUser={msg.role === 'user'}
              typing={idx === messages.slice(-6).length - 1 && msg.role === 'pet' && isPetTyping}
            />
          ))}
          {isPetTyping && messages[messages.length - 1]?.role === 'user' && (
            <div className="flex justify-start animate-fadeIn">
              <div className="bg-white/80 backdrop-blur rounded-2xl rounded-bl-sm px-4 py-3 shadow-sm border border-[#e0d0c0]/50">
                <div className="flex gap-1">
                  <span className="w-2 h-2 bg-[#c4a48a] rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                  <span className="w-2 h-2 bg-[#c4a48a] rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                  <span className="w-2 h-2 bg-[#c4a48a] rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                </div>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* 移动端输入框 */}
      <div className="md:hidden fixed bottom-20 left-0 right-0 px-4 z-40">
        <div className="max-w-md mx-auto flex items-center gap-1.5 bg-white/80 backdrop-blur-xl rounded-full px-3 py-2 shadow-lg border border-white/50 glow-border">
          {/* 语音开关按钮 */}
          <button
            onClick={toggleVoice}
            title={voiceEnabled ? '关闭语音播报' : '开启语音播报'}
            className={`w-7 h-7 flex items-center justify-center rounded-full transition-all flex-shrink-0 ${
              voiceEnabled
                ? 'text-[#c4a48a]'
                : 'text-[#c4b4a4] opacity-50'
            }`}
          >
            {voiceEnabled ? <Volume2 size={15} /> : <VolumeX size={15} />}
          </button>
          <input
            type="text"
            value={isListening ? interimText : inputText}
            onChange={e => { if (!isListening) setInputText(e.target.value); }}
            onKeyDown={e => e.key === 'Enter' && !isListening && handleSend()}
            placeholder={isListening ? '正在聆听...' : `和${pet.name}说说话...`}
            className={`flex-1 bg-transparent text-sm placeholder-[#c4b4a4] outline-none py-1 min-w-0 ${isListening ? 'text-[#c4a48a]' : 'text-[#5a4a3a]'}`}
          />
          {/* 语音输入麦克风按钮 */}
          {isSTTSupported() && (
            <button
              onClick={handleVoiceInput}
              title={isListening ? '停止语音输入' : '语音输入'}
              className={`w-7 h-7 flex items-center justify-center rounded-full transition-all flex-shrink-0 ${
                isListening
                  ? 'bg-[#e88a8a] text-white animate-pulse shadow-md'
                  : 'text-[#8b6f5e]'
              }`}
            >
              <Mic size={13} />
            </button>
          )}
          <button
            onClick={handleSend}
            disabled={!inputText.trim() || isPetTyping || isListening}
            className={`w-7 h-7 flex items-center justify-center rounded-full transition-all flex-shrink-0 ${
              inputText.trim() && !isPetTyping && !isListening
                ? 'bg-gradient-to-br from-[#c4a48a] to-[#a08070] text-white shadow-md'
                : 'bg-[#e0d0c0] text-[#a09080]'
            }`}
          >
            <Send size={13} />
          </button>
        </div>
      </div>

      {/* 重新生成确认对话框 */}
      {showRegenerateConfirm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white/95 backdrop-blur rounded-3xl p-6 mx-8 max-w-sm w-full shadow-2xl border border-[#e0d0c0]/50 glow-border">
            <div className="text-center">
              <div className="w-14 h-14 mx-auto mb-4 rounded-full bg-[#fdf6f0] flex items-center justify-center">
                <RefreshCw size={24} className="text-[#c4a48a]" />
              </div>
              <h3 className="text-lg font-medium text-[#5a4a3a] mb-2" style={{ fontFamily: 'Georgia, "Noto Serif SC", serif' }}>
                重新生成形象？
              </h3>
              <p className="text-sm text-[#8b6f5e] leading-relaxed mb-6">
                将回到创建页面，你需要重新上传照片并填写信息。当前宠物形象会被替换。
              </p>
              <div className="flex gap-3">
                <button
                  onClick={() => setShowRegenerateConfirm(false)}
                  className="flex-1 py-2.5 rounded-full bg-[#f0e0d0] text-[#8b6f5e] text-sm font-medium hover:bg-[#e8d8c8] transition-all"
                >
                  再想想
                </button>
                <button
                  onClick={confirmRegenerate}
                  className="flex-1 py-2.5 rounded-full bg-gradient-to-r from-[#c4a48a] to-[#a08070] text-white text-sm font-medium shadow-md hover:shadow-lg transition-all"
                >
                  确定重新生成
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <NavBar />
    </div>
  );
}
