import { HashRouter as Router, Routes, Route, Navigate, useLocation } from "react-router-dom";
import Welcome from "@/pages/Welcome";
import Create from "@/pages/Create";
import Home from "@/pages/Home";
import Features from "@/pages/Features";
import MoodSense from "@/pages/MoodSense";
import Diary from "@/pages/Diary";
import Postcard from "@/pages/Postcard";
import Memory from "@/pages/Memory";
import Goodbye from "@/pages/Goodbye";
import Admin from "@/pages/Admin";
import Timeline from "@/pages/Timeline";
import PageTransition from "@/components/PageTransition";
import TitleBar from "@/components/TitleBar";

/**
 * 应用主体内容
 * 根据当前路由决定是否显示标题栏
 */
function AppContent() {
  const location = useLocation();
  // 告别页面为全屏沉浸式，不显示标题栏
  const immersiveRoutes = ['/memory/goodbye'];
  const showTitleBar = !immersiveRoutes.includes(location.pathname);

  return (
    <>
      {showTitleBar && <TitleBar />}
      <PageTransition>
        <Routes>
          <Route path="/" element={<Welcome />} />
          <Route path="/welcome" element={<Welcome />} />
          <Route path="/create" element={<Create />} />
          <Route path="/home" element={<Home />} />
          <Route path="/features" element={<Features />} />
          <Route path="/features/mood" element={<MoodSense />} />
          <Route path="/features/diary" element={<Diary />} />
          <Route path="/features/postcard" element={<Postcard />} />
          <Route path="/memory" element={<Memory />} />
          <Route path="/memory/goodbye" element={<Goodbye />} />
          <Route path="/memory/timeline" element={<Timeline />} />
          <Route path="/admin" element={<Admin />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </PageTransition>
    </>
  );
}

/**
 * 应用根组件
 */
export default function App() {
  return (
    <Router>
      <AppContent />
    </Router>
  );
}
