import { usePetStore } from '@/store/usePetStore';
import { Heart, Sparkles, Hand } from 'lucide-react';

/**
 * 宠物状态面板组件
 * 显示心情值、亲密度、今日互动次数
 */
export default function StatusBar() {
  const pet = usePetStore(s => s.pet);

  if (!pet) return null;

  const stats = [
    { icon: Heart, label: '心情', value: pet.mood, color: '#e8a0a0', bg: 'rgba(232,160,160,0.15)' },
    { icon: Sparkles, label: '亲密', value: pet.intimacy, color: '#c4a48a', bg: 'rgba(196,164,138,0.15)' },
    { icon: Hand, label: '互动', value: Math.min(pet.interactCount * 10, 100), color: '#a0b8d0', bg: 'rgba(160,184,208,0.15)', count: pet.interactCount },
  ];

  return (
    <div className="flex gap-3 justify-center">
      {stats.map(stat => {
        const Icon = stat.icon;
        return (
          <div key={stat.label} className="flex items-center gap-2 bg-white/60 backdrop-blur rounded-full px-3 py-1.5 glow-border">
            <Icon size={14} style={{ color: stat.color }} />
            <span className="text-xs text-[#8b6f5e]">{stat.label}</span>
            <div className="w-16 h-2 rounded-full" style={{ background: stat.bg }}>
              <div
                className="h-full rounded-full transition-all duration-500"
                style={{ width: `${stat.value}%`, background: stat.color, boxShadow: `0 0 8px ${stat.color}80` }}
              />
            </div>
            {stat.count !== undefined && (
              <span className="text-xs font-medium" style={{ color: stat.color }}>{stat.count}</span>
            )}
          </div>
        );
      })}
    </div>
  );
}
