import { useNavigate } from 'react-router-dom';
import { ArrowLeft, MessageCircle, BookOpen, Mail } from 'lucide-react';
import { usePetStore } from '@/store/usePetStore';
import NavBar from '@/components/NavBar';

/** 时间线条目类型 */
interface TimelineEntry {
  id: string;
  timestamp: string;
  type: 'message' | 'diary' | 'postcard';
  title: string;
  content: string;
  icon: typeof MessageCircle;
  color: string;
}

/**
 * 回忆时间线页面
 * 将对话、日记、明信片按时间倒序串成可视化时间线
 * 比赛演示亮点功能：展示用户与宠物的所有互动历史
 */
export default function Timeline() {
  const navigate = useNavigate();
  const pet = usePetStore(s => s.pet);
  const messages = usePetStore(s => s.messages);
  const diaries = usePetStore(s => s.diaries);
  const postcards = usePetStore(s => s.postcards);

  /** 合并所有互动记录并按时间倒序排列 */
  const buildTimeline = (): TimelineEntry[] => {
    const entries: TimelineEntry[] = [];

    // 对话消息（同时展示用户和宠物的对话，保留完整上下文）
    messages.forEach(m => {
      const isPet = m.role === 'pet';
      entries.push({
        id: m.id,
        timestamp: m.timestamp,
        type: 'message',
        title: isPet ? `${pet?.name || '它'}说` : '你说',
        content: m.content,
        icon: isPet ? MessageCircle : MessageCircle,
        color: isPet ? 'from-[#c4a48a] to-[#a08070]' : 'from-[#9bb8d4] to-[#7a9bc0]',
      });
    });

    // 日记
    diaries.forEach(d => {
      entries.push({
        id: d.id,
        timestamp: new Date(d.date).toISOString(),
        type: 'diary',
        title: `它的一天 · ${d.weather}`,
        content: d.content,
        icon: BookOpen,
        color: 'from-[#d4b896] to-[#c4a48a]',
      });
    });

    // 明信片
    postcards.forEach(p => {
      entries.push({
        id: p.id,
        timestamp: p.createdAt,
        type: 'postcard',
        title: '彩虹桥明信片',
        content: `你：${p.userMessage.slice(0, 40)}${p.userMessage.length > 40 ? '...' : ''}`,
        icon: Mail,
        color: 'from-[#b4a0dc] to-[#9080c0]',
      });
    });

    // 按时间倒序
    return entries.sort((a, b) =>
      new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
    );
  };

  const timeline = buildTimeline();

  /** 格式化时间显示 */
  const formatTime = (ts: string) => {
    const date = new Date(ts);
    const now = new Date();
    const diff = now.getTime() - date.getTime();
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    if (days === 0) {
      return `今天 ${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;
    } else if (days === 1) {
      return '昨天';
    } else if (days < 7) {
      return `${days}天前`;
    } else {
      return `${date.getMonth() + 1}月${date.getDate()}日`;
    }
  };

  return (
    <div className="min-h-screen pb-24 md:pb-4 pt-20 md:pt-28" style={{ background: 'linear-gradient(180deg, #fdf6f0 0%, #f8efe5 100%)' }}>
      {/* 顶部 */}
      <div className="flex items-center px-4 md:px-8 py-3 max-w-3xl mx-auto">
        <button
          onClick={() => navigate('/memory')}
          className="w-10 h-10 flex items-center justify-center rounded-full bg-white/60 backdrop-blur text-[#8b6f5e] hover:bg-white/80 transition-colors glow-hover"
        >
          <ArrowLeft size={20} />
        </button>
        <h1 className="flex-1 text-center text-lg font-medium text-[#5a4a3a] mr-10" style={{ fontFamily: 'Georgia, "Noto Serif SC", serif' }}>
          回忆时间线
        </h1>
      </div>

      <div className="px-6 md:px-8 max-w-2xl mx-auto">
        <p className="text-center text-sm text-[#a08c7a] mb-8">
          和{pet?.name || '它'}的每一段时光，都在这里
        </p>

        {timeline.length === 0 ? (
          <div className="text-center py-20">
            <div className="text-5xl mb-4 opacity-30">🐾</div>
            <p className="text-[#a08c7a] text-sm">还没有回忆，去和它互动吧</p>
          </div>
        ) : (
          /* 时间线 */
          <div className="relative">
            {/* 竖线 */}
            <div className="absolute left-5 top-0 bottom-0 w-0.5 bg-gradient-to-b from-[#c4a48a]/40 via-[#c4a48a]/20 to-transparent" />

            {timeline.map((entry, idx) => {
              const Icon = entry.icon;
              return (
                <div
                  key={entry.id}
                  className="relative flex gap-4 mb-6 animate-fadeIn"
                  style={{ animationDelay: `${idx * 50}ms` }}
                >
                  {/* 时间点图标 */}
                  <div className={`relative z-10 w-10 h-10 rounded-full bg-gradient-to-br ${entry.color} flex items-center justify-center text-white shadow-md flex-shrink-0`}>
                    <Icon size={16} />
                  </div>

                  {/* 内容卡片 */}
                  <div className="flex-1 bg-white/70 backdrop-blur rounded-2xl p-4 border border-[#e0d0c0]/40 shadow-sm hover:shadow-md transition-all glow-border">
                    <div className="flex items-center justify-between mb-2">
                      <span className="text-sm font-medium text-[#5a4a3a]">{entry.title}</span>
                      <span className="text-xs text-[#b0a090]">{formatTime(entry.timestamp)}</span>
                    </div>
                    <p className="text-sm text-[#6b5b4b] leading-relaxed line-clamp-3">{entry.content}</p>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      <NavBar />
    </div>
  );
}
