import { useState, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Upload, Camera, ChevronDown, Check, X, Sparkles } from 'lucide-react';
import { usePetStore } from '@/store/usePetStore';
import { personalities, species, dogBreeds, catBreeds, rabbitBreeds, hamsterBreeds, birdBreeds } from '@/data/personalities';
import { delay, compressImage } from '@/utils/helpers';

/** Electron API 类型声明（含魔搭生图 + 用量查询） */
interface ElectronAPI {
  /** 有照片：两步法生成 */
  generatePetFromPhoto: (photoBase64: string) => Promise<{
    success: boolean;
    imageUrl?: string;
    description?: string;
    error?: string;
  }>;
  /** 无照片：根据品种特征生成 */
  generatePetFromInfo: (info: { species: string; breed: string; features: string }) => Promise<{
    success: boolean;
    imageUrl?: string;
    error?: string;
  }>;
}

/**
 * 获取 Electron API（非 Electron 环境返回 null）
 */
function getElectronAPI(): ElectronAPI | null {
  return (window as Window & { electronAPI?: ElectronAPI }).electronAPI ?? null;
}

/**
 * 宠物创建页
 * 上传照片 + 填写信息 + AI生成动画
 * 使用魔搭两步法（视觉分析→高质量生图）生成真实形象，无照片时根据品种特征生成
 */
export default function Create() {
  const navigate = useNavigate();
  const createPet = usePetStore(s => s.createPet);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [photoData, setPhotoData] = useState<string>('');
  const [name, setName] = useState('');
  const [selectedSpecies, setSelectedSpecies] = useState('');
  const [isMixed, setIsMixed] = useState(false);
  const [breed, setBreed] = useState('');
  const [breed2, setBreed2] = useState('');
  const [selectedPersonalities, setSelectedPersonalities] = useState<string[]>([]);
  const [features, setFeatures] = useState('');
  /** 生日（YYYY-MM-DD，可选） */
  const [birthday, setBirthday] = useState('');
  /** 离世日期（YYYY-MM-DD，可选） */
  const [passingDate, setPassingDate] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [genProgress, setGenProgress] = useState(0);
  const [genText, setGenText] = useState('');
  const [uploading, setUploading] = useState(false);

  const getBreeds = () => {
    switch (selectedSpecies) {
      case 'dog': return dogBreeds;
      case 'cat': return catBreeds;
      case 'rabbit': return rabbitBreeds;
      case 'hamster': return hamsterBreeds;
      case 'bird': return birdBreeds;
      default: return [];
    }
  };
  const breeds = getBreeds();

  const handleFileUpload = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setUploading(true);
      try {
        const compressed = await compressImage(file, 200, 0.6);
        setPhotoData(compressed);
      } finally {
        setUploading(false);
      }
    }
  }, []);

  const togglePersonality = (id: string) => {
    setSelectedPersonalities(prev =>
      prev.includes(id) ? prev.filter(p => p !== id) : prev.length < 3 ? [...prev, id] : prev
    );
  };

  const canGenerate = !!name.trim() && !!selectedSpecies && selectedPersonalities.length > 0 && (!isMixed || (breed && breed2));

  const getBreedString = () => {
    if (isMixed && breed && breed2) return `${breed} × ${breed2}`;
    if (breed) return breed;
    const s = species.find(sp => sp.id === selectedSpecies);
    return s ? s.label : '小伙伴';
  };

  const handleGenerate = async () => {
    if (!canGenerate) return;
    setIsGenerating(true);

    const breedStr = getBreedString();
    let finalImageUrl = '';

    const api = getElectronAPI();

    /**
     * 启动进度模拟器：在 from~to 范围内逐步增长进度
     * 避免长时间 API 调用时进度条卡住
     * @returns 停止函数
     */
    const startProgressSimulator = (from: number, to: number, text: string) => {
      setGenText(text);
      let current = from;
      const stepCount = 20;
      const stepSize = (to - from) / stepCount;
      const timer = setInterval(() => {
        current += stepSize;
        if (current >= to) {
          current = to;
          clearInterval(timer);
        }
        setGenProgress(Math.round(current));
      }, 500);
      return () => clearInterval(timer);
    };

    // 统一使用魔搭 API 生成（有照片两步法，无照片按品种特征）
    if (api) {
      const simText = photoData
        ? '正在端详它的模样，捕捉每个细节...'
        : '正在根据品种和特征想象它的样子...';
      const stopSim = startProgressSimulator(10, 70, simText);
      try {
        const result = photoData
          ? await api.generatePetFromPhoto(photoData)
          : await api.generatePetFromInfo({
              species: selectedSpecies,
              breed: breedStr,
              features: features.trim(),
            });
        stopSim();

        if (result.success && result.imageUrl) {
          setGenProgress(75);
          setGenText('AI 正在还原它的真实形象...');
          await delay(400);
          finalImageUrl = result.imageUrl;
        } else {
          throw new Error(result.error || '生成失败');
        }
      } catch (err) {
        stopSim();
        console.error('魔搭 API 生成失败:', err);
        setIsGenerating(false);
        alert(`生成失败：${err instanceof Error ? err.message : '未知错误'}\n请检查网络或稍后重试。`);
        return;
      }
    } else {
      // 非 Electron 环境（浏览器开发），无法生成
      setIsGenerating(false);
      alert('请在云上重逢应用中运行以使用 AI 生成功能。');
      return;
    }

    // 完成
    setGenProgress(90);
    setGenText('复原它的性格...');
    await delay(400);

    setGenProgress(100);
    setGenText('重逢了...');

    createPet({
      name: name.trim(),
      species: selectedSpecies,
      breed: breedStr,
      personality: selectedPersonalities,
      features: features.trim(),
      photoData: photoData || undefined,
      imageUrl: finalImageUrl,
      birthday: birthday || undefined,
      passingDate: passingDate || undefined,
    });

    await delay(200);
    navigate('/home', { replace: true });
  };

  // 生成中界面
  if (isGenerating) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center px-6" style={{ background: 'linear-gradient(135deg, #fdf6f0, #f5ebe0, #fdf6f0)' }}>
        <div className="text-center">
          {/* 光环动画 */}
          <div className="relative w-48 h-48 mx-auto mb-8">
            <div className="absolute inset-0 rounded-full" style={{ background: 'radial-gradient(circle, rgba(196,164,138,0.15) 0%, transparent 70%)' }} />
            <div className="absolute inset-2 rounded-full border-4 border-[#c4a48a]/15" />
            <div className="absolute inset-2 rounded-full border-4 border-[#c4a48a] border-t-transparent animate-spin" style={{ animationDuration: '2s' }} />
            <div className="absolute inset-6 rounded-full border-2 border-[#d4b896]/30 border-b-transparent animate-spin" style={{ animationDuration: '3s', animationDirection: 'reverse' }} />
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="relative">
                <span className="text-6xl animate-breathe block" style={{ animationDuration: '2s' }}>🐾</span>
                <Sparkles size={20} className="absolute -top-2 -right-4 text-[#d4a574] animate-pulse" />
                <Sparkles size={14} className="absolute -bottom-1 -left-5 text-[#c4a48a] animate-pulse" style={{ animationDelay: '0.5s' }} />
              </div>
            </div>
          </div>

          <p className="text-[#8b6f5e] text-xl mb-6 font-medium" style={{ fontFamily: 'Georgia, "Noto Serif SC", serif' }}>
            {genText}
          </p>

          {/* 进度条 */}
          <div className="w-72 h-2.5 bg-[#f0e0d0]/80 rounded-full mx-auto overflow-hidden shadow-inner">
            <div
              className="h-full rounded-full transition-all duration-500 ease-out relative"
              style={{
                width: `${genProgress}%`,
                background: 'linear-gradient(90deg, #d4b896, #c4a48a, #a08070)',
              }}
            >
              <div className="absolute right-0 top-0 h-full w-4 bg-white/40 rounded-full animate-pulse" />
            </div>
          </div>
          <p className="text-xs text-[#b8a898] mt-3 font-medium">{genProgress}%</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pb-28 md:pb-8 pt-20 md:pt-28" style={{ background: 'linear-gradient(180deg, #fdf6f0 0%, #f8efe5 100%)' }}>
      {/* 顶部栏 */}
      <div className="flex items-center px-4 md:px-8 py-3 max-w-5xl mx-auto">
        <button
          onClick={() => navigate(-1)}
          className="w-10 h-10 flex items-center justify-center rounded-full bg-white/70 backdrop-blur text-[#8b6f5e] hover:bg-white/90 transition-all shadow-sm glow-hover"
        >
          <ArrowLeft size={20} />
        </button>
        <h1 className="flex-1 text-center text-lg font-medium text-[#5a4a3a] mr-10" style={{ fontFamily: 'Georgia, "Noto Serif SC", serif' }}>
          让它回来
        </h1>
      </div>

      <div className="px-5 max-w-md mx-auto space-y-5">
        {/* 照片上传 */}
        <div className="glass-card glow-border p-6 text-center shadow-sm">
          <div
            onClick={() => !uploading && fileInputRef.current?.click()}
            className={`w-36 h-36 mx-auto rounded-2xl border-2 border-dashed flex flex-col items-center justify-center cursor-pointer transition-all overflow-hidden relative group ${
              photoData ? 'border-[#c4a48a]' : 'border-[#d4c0a8] hover:border-[#c4a48a] hover:bg-[#c4a48a]/5'
            }`}
            style={{ background: photoData ? 'transparent' : 'rgba(255,255,255,0.5)' }}
          >
            {uploading ? (
              <div className="flex flex-col items-center">
                <div className="w-8 h-8 border-3 border-[#c4a48a] border-t-transparent rounded-full animate-spin mb-2" />
                <span className="text-xs text-[#a08c7a]">处理中...</span>
              </div>
            ) : photoData ? (
              <>
                <img src={photoData} alt="宠物照片" className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/30 flex items-center justify-center transition-all">
                  <Camera size={24} className="text-white opacity-0 group-hover:opacity-100 transition-opacity" />
                </div>
                <button
                  onClick={(e) => { e.stopPropagation(); setPhotoData(''); }}
                  className="absolute top-1 right-1 w-6 h-6 bg-black/40 hover:bg-black/60 rounded-full flex items-center justify-center text-white opacity-0 group-hover:opacity-100 transition-opacity"
                >
                  <X size={14} />
                </button>
              </>
            ) : (
              <>
                <Upload size={28} className="text-[#c4a48a] mb-2" />
                <span className="text-sm text-[#a08c7a]">上传它的照片</span>
              </>
            )}
          </div>
          <input ref={fileInputRef} type="file" accept="image/*" onChange={handleFileUpload} className="hidden" />
          <p className="text-xs text-[#b0a090] mt-3">上传一张它最可爱的照片，帮助还原它的样子</p>
        </div>

        {/* 名字 */}
        <div className="glass-card glow-border p-5 shadow-sm">
          <label className="block text-sm font-medium text-[#8b6f5e] mb-2">它叫什么名字？</label>
          <input
            type="text"
            value={name}
            onChange={e => setName(e.target.value)}
            placeholder="输入它的名字..."
            maxLength={12}
            className="w-full bg-white/70 border border-[#e0d0c0] rounded-xl px-4 py-3 text-[#5a4a3a] placeholder-[#c4b4a4] focus:outline-none focus:border-[#c4a48a] focus:ring-2 focus:ring-[#c4a48a]/20 transition-all"
          />
        </div>

        {/* 品种 */}
        <div className="glass-card glow-border p-5 shadow-sm">
          <label className="block text-sm font-medium text-[#8b6f5e] mb-3">它是什么小动物？</label>
          <div className="flex flex-wrap gap-2 mb-4">
            {species.map(s => (
              <button
                key={s.id}
                onClick={() => { setSelectedSpecies(s.id); setBreed(''); setBreed2(''); setIsMixed(false); }}
                className={`flex items-center gap-1.5 px-4 py-2 rounded-full text-sm transition-all ${
                  selectedSpecies === s.id
                    ? 'bg-gradient-to-r from-[#c4a48a] to-[#a08070] text-white shadow-md scale-105'
                    : 'bg-white/60 text-[#8b6f5e] hover:bg-white/80 border border-[#e0d0c0]'
                }`}
              >
                <span className="text-base">{s.emoji}</span>
                <span>{s.label}</span>
              </button>
            ))}
          </div>

          {selectedSpecies && breeds.length > 0 && (
            <div className="space-y-3">
              {/* 混血开关 */}
              {['dog', 'cat'].includes(selectedSpecies) && (
                <button
                  onClick={() => { setIsMixed(!isMixed); setBreed2(''); }}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs transition-all ${
                    isMixed
                      ? 'bg-gradient-to-r from-[#d4a574] to-[#c4956a] text-white shadow-sm'
                      : 'bg-white/60 text-[#8b6f5e] border border-[#e0d0c0] hover:bg-white/80'
                  }`}
                >
                  <span>🌈</span>
                  <span>混血宝宝</span>
                  {isMixed && <Check size={12} />}
                </button>
              )}

              <div className="relative">
                <select
                  value={breed}
                  onChange={e => setBreed(e.target.value)}
                  className="w-full appearance-none bg-white/70 border border-[#e0d0c0] rounded-xl px-4 py-3 text-[#5a4a3a] focus:outline-none focus:border-[#c4a48a] transition-all"
                >
                  <option value="">选择品种{isMixed ? '（第一种）' : '（可选）'}</option>
                  {breeds.map(b => (
                    <option key={b} value={b}>{b}</option>
                  ))}
                </select>
                <ChevronDown size={16} className="absolute right-4 top-1/2 -translate-y-1/2 text-[#a08c7a] pointer-events-none" />
              </div>

              {isMixed && (
                <div className="relative">
                  <div className="absolute -left-1 top-1/2 -translate-y-1/2 text-[#c4a48a] font-bold text-sm z-10">×</div>
                  <select
                    value={breed2}
                    onChange={e => setBreed2(e.target.value)}
                    className="w-full appearance-none bg-white/70 border border-[#e0d0c0] rounded-xl pl-8 pr-10 py-3 text-[#5a4a3a] focus:outline-none focus:border-[#c4a48a] transition-all"
                  >
                    <option value="">选择品种（第二种）</option>
                    {breeds.filter(b => b !== breed).map(b => (
                      <option key={b} value={b}>{b}</option>
                    ))}
                  </select>
                  <ChevronDown size={16} className="absolute right-4 top-1/2 -translate-y-1/2 text-[#a08c7a] pointer-events-none" />
                </div>
              )}
            </div>
          )}
        </div>

        {/* 性格 */}
        <div className="glass-card glow-border p-5 shadow-sm">
          <label className="block text-sm font-medium text-[#8b6f5e] mb-2">
            它是什么性格？<span className="text-xs text-[#b0a090] font-normal ml-1">（选择1-3个）</span>
          </label>
          <div className="flex flex-wrap gap-2">
            {personalities.map(p => {
              const selected = selectedPersonalities.includes(p.id);
              return (
                <button
                  key={p.id}
                  onClick={() => togglePersonality(p.id)}
                  className={`flex items-center gap-1.5 px-3 py-2 rounded-full text-sm transition-all ${
                    selected
                      ? 'text-white shadow-md scale-105'
                      : 'bg-white/60 text-[#8b6f5e] hover:bg-white/80 border border-[#e0d0c0]'
                  }`}
                  style={selected ? { background: `linear-gradient(135deg, ${p.color}, #a08070)` } : undefined}
                >
                  <span>{p.emoji}</span>
                  <span>{p.label}</span>
                  {selected && <Check size={14} />}
                </button>
              );
            })}
          </div>
        </div>

        {/* 纪念日（可选） */}
        <div className="glass-card glow-border p-5 shadow-sm">
          <label className="block text-sm font-medium text-[#8b6f5e] mb-2">
            特别的日子<span className="text-xs text-[#b0a090] font-normal ml-1">（可选，用于纪念日仪式）</span>
          </label>
          <p className="text-xs text-[#b0a090] mb-3">
            填写后，在它的生日或离世周年时，会有特别的仪式和对话
          </p>
          <div className="space-y-3">
            <div className="relative">
              <label className="block text-xs text-[#a08c7a] mb-1">🎂 它的生日</label>
              <input
                type="date"
                value={birthday}
                onChange={e => setBirthday(e.target.value)}
                className="w-full bg-white/70 border border-[#e0d0c0] rounded-xl px-4 py-3 text-[#5a4a3a] focus:outline-none focus:border-[#c4a48a] focus:ring-2 focus:ring-[#c4a48a]/20 transition-all"
              />
            </div>
            <div className="relative">
              <label className="block text-xs text-[#a08c7a] mb-1">🌈 彩虹桥之日（离世日期）</label>
              <input
                type="date"
                value={passingDate}
                onChange={e => setPassingDate(e.target.value)}
                className="w-full bg-white/70 border border-[#e0d0c0] rounded-xl px-4 py-3 text-[#5a4a3a] focus:outline-none focus:border-[#c4a48a] focus:ring-2 focus:ring-[#c4a48a]/20 transition-all"
              />
            </div>
          </div>
        </div>

        {/* 特征描述 */}
        <div className="glass-card glow-border p-5 shadow-sm">
          <label className="block text-sm font-medium text-[#8b6f5e] mb-2">
            有什么特别的地方？<span className="text-xs text-[#b0a090] font-normal ml-1">（可选）</span>
          </label>
          <textarea
            value={features}
            onChange={e => setFeatures(e.target.value)}
            placeholder="比如：左耳有个小缺口、尾巴尖是白色的、听到塑料袋声音就会跑过来..."
            rows={3}
            maxLength={200}
            className="w-full bg-white/70 border border-[#e0d0c0] rounded-xl px-4 py-3 text-[#5a4a3a] placeholder-[#c4b4a4] focus:outline-none focus:border-[#c4a48a] focus:ring-2 focus:ring-[#c4a48a]/20 transition-all resize-none"
          />
        </div>

        {/* 生成按钮 */}
        <button
          onClick={handleGenerate}
          disabled={!canGenerate}
          className={`w-full py-4 rounded-2xl text-base font-medium tracking-wide transition-all shadow-lg ${
            canGenerate
              ? 'bg-gradient-to-r from-[#c4a48a] to-[#a08070] text-white hover:shadow-xl active:scale-[0.98] glow-hover'
              : 'bg-[#e0d0c0] text-[#a09080] cursor-not-allowed shadow-none'
          }`}
        >
          {canGenerate ? '✨ 让它回到我身边' : '填写信息后开始重逢'}
        </button>
      </div>
    </div>
  );
}
