import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, RefreshCw, TrendingUp, Database, AlertTriangle } from 'lucide-react';

/** 魔搭 API 用量信息 */
interface ApiUsageInfo {
  date: string;
  usedToday: number;
  remaining: number;
  totalUsed: number;
  quota: number;
}

/** Electron API 类型声明（用量查询部分） */
interface ElectronAPI {
  getApiUsage: () => Promise<ApiUsageInfo>;
  resetApiUsage: () => Promise<ApiUsageInfo>;
}

/**
 * 获取 Electron API
 */
function getElectronAPI(): ElectronAPI | null {
  return (window as Window & { electronAPI?: ElectronAPI }).electronAPI ?? null;
}

/**
 * 管理员后台：魔搭 API 用量监控
 * 显示当日用量、剩余额度、累计用量，支持刷新和重置
 */
export default function Admin() {
  const navigate = useNavigate();
  const [usage, setUsage] = useState<ApiUsageInfo | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  /** 拉取最新用量数据 */
  const fetchUsage = useCallback(async () => {
    const api = getElectronAPI();
    if (!api) {
      setError('请在云上重逢应用中运行以查看用量');
      setLoading(false);
      return;
    }
    try {
      setLoading(true);
      const data = await api.getApiUsage();
      setUsage(data);
      setError('');
    } catch (err) {
      setError(err instanceof Error ? err.message : '获取用量失败');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchUsage();
  }, [fetchUsage]);

  /** 重置用量（调试用） */
  const handleReset = async () => {
    const api = getElectronAPI();
    if (!api) return;
    if (!confirm('确定要重置 API 用量统计吗？此操作不可撤销。')) return;
    try {
      const data = await api.resetApiUsage();
      setUsage(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : '重置失败');
    }
  };

  /** 计算用量百分比（防御 quota 为 0 的除零情况） */
  const usedPercent = usage && usage.quota > 0 ? Math.round((usage.usedToday / usage.quota) * 100) : 0;

  return (
    <div className="min-h-screen pt-20 md:pt-28 pb-8" style={{ background: 'linear-gradient(180deg, #1a1a2e 0%, #16213e 100%)' }}>
      {/* 顶部栏 */}
      <div className="flex items-center px-4 md:px-8 py-3 max-w-4xl mx-auto">
        <button
          onClick={() => navigate(-1)}
          className="w-10 h-10 flex items-center justify-center rounded-full bg-white/10 backdrop-blur text-white/80 hover:bg-white/20 transition-all"
        >
          <ArrowLeft size={20} />
        </button>
        <h1 className="flex-1 text-center text-lg font-medium text-white mr-10" style={{ fontFamily: 'Georgia, "Noto Serif SC", serif' }}>
          管理后台 · API 用量监控
        </h1>
      </div>

      <div className="px-5 max-w-2xl mx-auto space-y-5">
        {error && (
          <div className="bg-red-500/20 border border-red-400/40 rounded-2xl p-4 flex items-center gap-2 text-red-300">
            <AlertTriangle size={18} />
            <span className="text-sm">{error}</span>
          </div>
        )}

        {/* 主用量卡片 */}
        {usage && (
          <div className="bg-white/5 backdrop-blur border border-white/10 rounded-3xl p-6 shadow-2xl">
            <div className="flex items-center justify-between mb-6">
              <div className="flex items-center gap-2">
                <Database size={20} className="text-cyan-400" />
                <h2 className="text-white font-medium">魔搭 API-Inference</h2>
              </div>
              <span className="text-xs text-white/40">{usage.date}</span>
            </div>

            {/* 今日用量大数字 */}
            <div className="text-center mb-6">
              <div className="text-5xl font-bold text-white mb-1">
                {usage.usedToday}
                <span className="text-2xl text-white/40"> / {usage.quota}</span>
              </div>
              <p className="text-sm text-white/50">今日已调用 / 每日免费额度</p>
            </div>

            {/* 进度条 */}
            <div className="mb-2">
              <div className="w-full h-3 bg-white/10 rounded-full overflow-hidden">
                <div
                  className={`h-full rounded-full transition-all duration-500 ${
                    usedPercent > 80 ? 'bg-gradient-to-r from-red-500 to-orange-500' :
                    usedPercent > 50 ? 'bg-gradient-to-r from-yellow-500 to-amber-500' :
                    'bg-gradient-to-r from-cyan-500 to-blue-500'
                  }`}
                  style={{ width: `${Math.min(100, usedPercent)}%` }}
                />
              </div>
              <div className="flex justify-between mt-1.5 text-xs text-white/40">
                <span>已用 {usedPercent}%</span>
                <span>剩余 {usage.remaining} 次</span>
              </div>
            </div>
          </div>
        )}

        {/* 统计卡片网格 */}
        {usage && (
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white/5 backdrop-blur border border-white/10 rounded-2xl p-5">
              <div className="flex items-center gap-2 mb-2">
                <TrendingUp size={16} className="text-green-400" />
                <span className="text-xs text-white/50">剩余额度</span>
              </div>
              <div className="text-2xl font-bold text-white">{usage.remaining}</div>
              <div className="text-xs text-white/30 mt-1">今日还可调用</div>
            </div>

            <div className="bg-white/5 backdrop-blur border border-white/10 rounded-2xl p-5">
              <div className="flex items-center gap-2 mb-2">
                <Database size={16} className="text-purple-400" />
                <span className="text-xs text-white/50">累计调用</span>
              </div>
              <div className="text-2xl font-bold text-white">{usage.totalUsed}</div>
              <div className="text-xs text-white/30 mt-1">历史总次数</div>
            </div>
          </div>
        )}

        {/* 额度说明 */}
        <div className="bg-white/5 backdrop-blur border border-white/10 rounded-2xl p-5">
          <h3 className="text-white/80 text-sm font-medium mb-3">额度说明</h3>
          <ul className="space-y-2 text-xs text-white/50">
            <li>· 魔搭 API-Inference 每日免费额度：2000 次</li>
            <li>· 用量数据持久化存储，重启应用不丢失</li>
            <li>· 每日凌晨自动重置当日计数</li>
            <li>· 累计调用次数跨日保留，用于长期统计</li>
            <li>· 每次生成宠物形象消耗 2 次（视觉分析 + 生图各 1 次）</li>
          </ul>
        </div>

        {/* 操作按钮 */}
        <div className="flex gap-3">
          <button
            onClick={fetchUsage}
            disabled={loading}
            className="flex-1 flex items-center justify-center gap-2 py-3 rounded-2xl bg-white/10 backdrop-blur text-white/80 text-sm font-medium hover:bg-white/20 transition-all disabled:opacity-50"
          >
            <RefreshCw size={16} className={loading ? 'animate-spin' : ''} />
            <span>{loading ? '刷新中...' : '刷新数据'}</span>
          </button>
          <button
            onClick={handleReset}
            className="flex-1 flex items-center justify-center gap-2 py-3 rounded-2xl bg-red-500/20 border border-red-400/30 text-red-300 text-sm font-medium hover:bg-red-500/30 transition-all"
          >
            <RefreshCw size={16} />
            <span>重置统计</span>
          </button>
        </div>

        {loading && !usage && (
          <div className="text-center py-8">
            <div className="w-8 h-8 border-2 border-white/20 border-t-cyan-400 rounded-full animate-spin mx-auto" />
            <p className="text-white/40 text-sm mt-3">加载中...</p>
          </div>
        )}
      </div>
    </div>
  );
}
