export type EmotionType = 'happy' | 'sad' | 'angry' | 'anxious' | 'tired' | 'neutral';

const emotionKeywords: Record<EmotionType, string[]> = {
  happy: ['开心', '高兴', '快乐', '哈哈', '嘻嘻', '好棒', '太好了', '赞', '喜欢', '爱', '爽', '耶', '棒', '嘿嘿', '笑', '愉快', '兴奋', '惊喜', '满足', '幸福'],
  sad: ['难过', '伤心', '哭', '悲伤', '失落', '沮丧', '不开心', '难受', '心痛', '痛苦', '呜呜', '想哭', '遗憾', '孤独', '寂寞', '想念', '思念', '想你', '走了', '离开'],
  angry: ['生气', '气死', '烦', '讨厌', '愤怒', '可恶', '混蛋', '滚', '恨', '恼火', '不爽', '气死我了'],
  anxious: ['紧张', '焦虑', '害怕', '担心', '不安', '慌', '忐忑', '压力', '好累', '撑不住', '崩溃', '迷茫', '不知道怎么办'],
  tired: ['累', '困', '疲惫', '想睡', '没精神', '好累', '乏', '精疲力尽', '不想动', '腰疼', '眼睛酸'],
  neutral: [],
};

const positiveWords = ['好', '棒', '美', '赞', '喜欢', '开心', '顺利', '成功', '赢', '赚', '升职', '加薪', '放假', '休息'];
const negativeWords = ['不', '没', '别', '坏', '差', '糟', '烂', '失败', '错', '痛', '病', '分手', '吵架'];

export function analyzeEmotion(text: string): { emotion: EmotionType; score: number; confidence: number } {
  if (!text || text.trim().length === 0) {
    return { emotion: 'neutral', score: 0.5, confidence: 0 };
  }

  const scores: Record<EmotionType, number> = {
    happy: 0, sad: 0, angry: 0, anxious: 0, tired: 0, neutral: 0.1,
  };

  for (const [emotion, keywords] of Object.entries(emotionKeywords)) {
    for (const keyword of keywords) {
      if (text.includes(keyword)) {
        scores[emotion as EmotionType] += 1;
      }
    }
  }

  const exclamationCount = (text.match(/[！!]/g) || []).length;
  if (exclamationCount > 0) {
    if (scores.happy > 0) scores.happy += exclamationCount * 0.3;
    if (scores.angry > 0) scores.angry += exclamationCount * 0.3;
    if (scores.sad > 0) scores.sad += exclamationCount * 0.2;
  }

  let maxEmotion: EmotionType = 'neutral';
  let maxScore = 0;
  for (const [emotion, score] of Object.entries(scores)) {
    if (score > maxScore) {
      maxScore = score;
      maxEmotion = emotion as EmotionType;
    }
  }

  const totalScore = Object.values(scores).reduce((a, b) => a + b, 0);
  const confidence = totalScore > 0 ? Math.min(maxScore / totalScore, 1) : 0;

  if (maxScore < 0.5) {
    let posCount = 0, negCount = 0;
    for (const w of positiveWords) if (text.includes(w)) posCount++;
    for (const w of negativeWords) if (text.includes(w)) negCount++;
    if (posCount > negCount) return { emotion: 'happy', score: 0.5, confidence: 0.3 };
    if (negCount > posCount) return { emotion: 'sad', score: 0.4, confidence: 0.3 };
    return { emotion: 'neutral', score: 0.5, confidence: 0 };
  }

  const normalizedScore = Math.min(0.3 + maxScore * 0.2, 1);
  return { emotion: maxEmotion, score: normalizedScore, confidence };
}

export function getPetReaction(emotion: EmotionType): { action: string; reply: string; petEmotion: string } {
  switch (emotion) {
    case 'happy':
      return {
        action: 'jump',
        reply: '看到你开心，我尾巴都要摇断了！💗 有好事对不对？快告诉我！',
        petEmotion: 'excited'
      };
    case 'sad':
      return {
        action: 'snuggle',
        reply: '（安安静静走过来，把头靠在你腿上）没关系，我在这里陪着你。想哭就哭吧，我的毛软软的。',
        petEmotion: 'calm'
      };
    case 'angry':
      return {
        action: 'lick',
        reply: '（舔舔你的手）别生气啦…气坏了身体不好。要不摸摸我消消气？',
        petEmotion: 'calm'
      };
    case 'anxious':
      return {
        action: 'snuggle',
        reply: '（蹭蹭你的手）别紧张，深呼吸。你已经做得很好了，不管怎么样我都在。',
        petEmotion: 'calm'
      };
    case 'tired':
      return {
        action: 'sleep',
        reply: '累了就休息一下吧…来，靠着我睡一会儿，我帮你守着。zzZ',
        petEmotion: 'sleepy'
      };
    default:
      return {
        action: 'blink',
        reply: '（歪头看着你）呜？怎么啦？我在听呢～',
        petEmotion: 'calm'
      };
  }
}
