export function generateDiary(date?: string): { id: string; date: string; content: string; weather: string; mood: string } {
  const template = diaryTemplates[Math.floor(Math.random() * diaryTemplates.length)];
  const content = template.contents[Math.floor(Math.random() * template.contents.length)];
  const now = date || new Date().toLocaleDateString('zh-CN', { month: 'long', day: 'numeric' });
  return {
    id: Date.now().toString(),
    date: now,
    content,
    weather: template.weather,
    mood: template.mood,
  };
}

