import { useState, useEffect } from 'react';
import { Minus, Square, X, Copy } from 'lucide-react';

/** Electron API 类型声明（窗口控制） */
interface WindowControlAPI {
  minimize: () => void;
  maximize: () => void;
  close: () => void;
  quitApp: () => void;
  isMaximized: () => Promise<boolean>;
  onMaximizeChange: (cb: (max: boolean) => void) => void;
}

/**
 * 获取 Electron 窗口控制 API
 */
function getWindowAPI(): WindowControlAPI | undefined {
  return (window as Window & { electronAPI?: WindowControlAPI }).electronAPI;
}

/**
 * 自定义标题栏组件
 * 桌面端：显示应用名称 + 最小化/最大化/关闭按钮
 * 移动端：仅显示窗口控制按钮
 * 可拖拽移动窗口（通过 CSS -webkit-app-region: drag 实现）
 * 关闭按钮：弹出确认对话框（是→退出，否→最小化到托盘）
 */
export default function TitleBar() {
  const [isMaximized, setIsMaximized] = useState(false);
  /** 是否显示关闭确认对话框 */
  const [showCloseConfirm, setShowCloseConfirm] = useState(false);

  useEffect(() => {
    const api = getWindowAPI();
    if (!api) return;
    api.isMaximized().then(setIsMaximized);
    api.onMaximizeChange((max: boolean) => {
      setIsMaximized(max);
    });
  }, []);

  /** 处理最小化 */
  const handleMinimize = () => {
    getWindowAPI()?.minimize();
  };

  /** 处理最大化/还原切换 */
  const handleMaximize = () => {
    getWindowAPI()?.maximize();
  };

  /** 处理关闭：弹出确认对话框 */
  const handleClose = () => {
    setShowCloseConfirm(true);
  };

  /** 确认退出：真正关闭应用 */
  const confirmQuit = () => {
    setShowCloseConfirm(false);
    getWindowAPI()?.quitApp();
  };

  /** 取消退出：隐藏对话框并最小化到托盘 */
  const cancelQuit = () => {
    setShowCloseConfirm(false);
    getWindowAPI()?.close();
  };

  return (
    <>
      <div
        className="fixed top-0 left-0 right-0 h-9 flex items-center justify-between px-3 z-[9999] bg-[#fef3e8]/80 backdrop-blur-sm border-b border-transparent"
        style={{ WebkitAppRegion: 'drag' } as React.CSSProperties}
      >
        {/* 桌面端应用名称 */}
        <div className="hidden md:flex items-center gap-2 pointer-events-none">
          <span className="text-xs font-medium text-[#8b6f5e] tracking-wide" style={{ fontFamily: 'Georgia, serif' }}>
            云上 · 陪伴
          </span>
        </div>

        {/* 底部渐变微光线 - 科技点缀 */}
        <div className="absolute bottom-0 left-0 right-0 h-px glow-line" />

        {/* 窗口控制按钮组 */}
        <div className="flex items-center gap-1 ml-auto" style={{ WebkitAppRegion: 'no-drag' } as React.CSSProperties}>
          {/* 最小化 */}
          <button
            onClick={handleMinimize}
            className="w-8 h-7 flex items-center justify-center rounded-md text-[#8b6f5e] hover:bg-[#e0d0c0]/50 hover:shadow-[0_0_10px_rgba(196,164,138,0.3)] transition-all"
            title="最小化"
          >
            <Minus size={16} />
          </button>

          {/* 最大化/还原 */}
          <button
            onClick={handleMaximize}
            className="w-8 h-7 flex items-center justify-center rounded-md text-[#8b6f5e] hover:bg-[#e0d0c0]/50 hover:shadow-[0_0_10px_rgba(196,164,138,0.3)] transition-all"
            title={isMaximized ? '还原' : '最大化'}
          >
            {isMaximized ? <Copy size={14} /> : <Square size={14} />}
          </button>

          {/* 关闭 */}
          <button
            onClick={handleClose}
            className="w-8 h-7 flex items-center justify-center rounded-md text-[#8b6f5e] hover:bg-[#e88a8a] hover:text-white hover:shadow-[0_0_10px_rgba(232,138,138,0.4)] transition-all"
            title="关闭"
          >
            <X size={16} />
          </button>
        </div>
      </div>

      {/* 关闭确认对话框 */}
      {showCloseConfirm && (
        <div className="fixed inset-0 z-[10000] flex items-center justify-center bg-black/40 backdrop-blur-sm animate-fadeIn" style={{ WebkitAppRegion: 'no-drag' } as React.CSSProperties}>
          <div className="bg-white/95 backdrop-blur rounded-3xl p-6 mx-8 max-w-sm w-full shadow-2xl border border-[#e0d0c0]/50 glow-border">
            <div className="text-center">
              <div className="w-14 h-14 mx-auto mb-4 rounded-full bg-[#fdf6f0] flex items-center justify-center">
                <X size={24} className="text-[#c4a48a]" />
              </div>
              <h3 className="text-lg font-medium text-[#5a4a3a] mb-2" style={{ fontFamily: 'Georgia, "Noto Serif SC", serif' }}>
                要退出云上重逢吗？
              </h3>
              <p className="text-sm text-[#8b6f5e] leading-relaxed mb-6">
                选择"退出"将关闭应用，选择"最小化"会藏在系统托盘，宠物依然陪着你。
              </p>
              <div className="flex gap-3">
                <button
                  onClick={cancelQuit}
                  className="flex-1 py-2.5 rounded-full bg-[#f0e0d0] text-[#8b6f5e] text-sm font-medium hover:bg-[#e8d8c8] transition-all"
                >
                  最小化到托盘
                </button>
                <button
                  onClick={confirmQuit}
                  className="flex-1 py-2.5 rounded-full bg-gradient-to-r from-[#e88a8a] to-[#d07070] text-white text-sm font-medium shadow-md hover:shadow-lg transition-all"
                >
                  退出
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
}
