import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { usePetStore } from '@/store/usePetStore';

/**
 * 欢迎页/启动页
 * 品牌开场动画，引导用户进入产品
 */
export default function Welcome() {
  const navigate = useNavigate();
  const hasOnboarded = usePetStore(s => s.hasOnboarded);
  const pet = usePetStore(s => s.pet);
  const [showContent, setShowContent] = useState(false);
  const [showButton, setShowButton] = useState(false);
  const [pawScale, setPawScale] = useState(0);

  useEffect(() => {
    // 如果已有宠物，直接跳转到主页；首次打开无宠物直接进入创建页（上传图片）
    if (hasOnboarded && pet) {
      navigate('/home', { replace: true });
      return;
    }
    // 首次打开（无宠物），直接跳转创建页
    navigate('/create', { replace: true });
  }, [hasOnboarded, pet, navigate]);

  return (
    <div className="min-h-screen flex flex-col items-center justify-center px-6 relative overflow-hidden">
      {/* 背景光晕 */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-[#e8c49a]/20 rounded-full blur-3xl" />
        <div className="absolute bottom-1/4 right-1/4 w-80 h-80 bg-[#d4b8d8]/15 rounded-full blur-3xl" />
      </div>

      <div className="relative z-10 text-center">
        {/* 爪印Logo */}
        <div
          className="transition-all duration-1000 ease-out mb-8 glow-pulse rounded-full"
          style={{ transform: `scale(${pawScale})`, opacity: pawScale }}
        >
          <svg width="80" height="80" viewBox="0 0 80 80" className="mx-auto animate-float">
            <circle cx="30" cy="28" r="10" fill="none" stroke="#c4a48a" strokeWidth="2.5" />
            <circle cx="16" cy="40" r="7" fill="none" stroke="#c4a48a" strokeWidth="2.5" />
            <circle cx="50" cy="28" r="10" fill="none" stroke="#c4a48a" strokeWidth="2.5" />
            <circle cx="64" cy="40" r="7" fill="none" stroke="#c4a48a" strokeWidth="2.5" />
            <ellipse cx="40" cy="55" rx="20" ry="16" fill="none" stroke="#c4a48a" strokeWidth="2.5" />
          </svg>
        </div>

        {/* 标题 */}
        <div className={`transition-all duration-1000 ${showContent ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
          <h1
            className="text-5xl font-bold mb-3 tracking-widest"
            style={{
              background: 'linear-gradient(135deg, #c4a48a 0%, #8b6f5e 50%, #6b5240 100%)',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              fontFamily: 'Georgia, "Noto Serif SC", serif',
            }}
          >
            云上重逢
          </h1>
          <p className="text-[#a08c7a] text-base tracking-widest mb-2">如果想念有声音</p>
          <p className="text-[#b8a898] text-sm tracking-wide">让它住在云端，陪在你身边</p>
        </div>

        {/* 开始按钮 */}
        <div className={`mt-16 transition-all duration-700 ${showButton ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
          <button
            onClick={() => navigate('/create')}
            className="warm-btn text-base px-10 py-3 tracking-wider glow-hover"
          >
            开始重逢
          </button>
          <p className="mt-4 text-xs text-[#c4b4a4]">世界很大，放手去造</p>
        </div>
      </div>
    </div>
  );
}
